let events=read('events',seed),tickets=read('tickets',[]),user=read('user',null),wallet='',order=null,payment='qris',payType='bot',chainAvail={},liveTimer=null,paid=false,busy=false,machine=null,loginScene=null,loginSceneVersion=0,carousel=null,searchQuery="",searchCity="",searchMode="",heroTicket=null,timer=null,tour=null,returnTo='/discover';
try{user ||= JSON.parse(sessionStorage.getItem('tr2:user'))}catch{}
const icon=(name)=>{const paths={ticket:'<path d="M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4V6Z"/><path d="M15 7v2m0 2v2m0 2v2"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',music:'<path d="M9 18V5l12-2v13M9 8l12-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="18" cy="16" rx="3" ry="3"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M16 10h5v5h-5zM3 8V5l14-3v3"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.ticket}</svg>`};
