const posterBySlug={'neon-after-midnight':'velora','echoes-live-orchestra':'nara','city-lights-tour':'kairo','pulse-fest':'pulse','nova-world-tour':'nova','blue-hour':'sora'};
const posterImage=e=>e?.artwork||(e?.slug&&posterBySlug[e.slug]?`./assets/posters/${posterBySlug[e.slug]}-v2.webp`:'./assets/hero.webp');
function poster(e){return `<div class="poster ${e.color}"><img src="${esc(posterImage(e))}" alt="Original artwork for ${esc(e.title)} by ${esc(e.artist)}" loading="lazy"><span class="poster-label">TICKETRUE PRESENTS</span><span class="mode-label">${e.mode==='seat'?'Seat selection':'Ticket tiers'}</span><div class="poster-copy"><span>${esc(e.artist)}</span><h3>${esc(e.title)}</h3><small>${date(e.date).toUpperCase()} · ${esc(e.city.toUpperCase())}</small></div></div>`}
function card(e){return `<a class="card" href="#/event/${e.slug}">${poster(e)}<span class="stock-slot" data-stock="${e.id}">${stockBadge(e)}</span>${heartBtn(e)}<div class="card-meta"><div><h3>${esc(e.title)}</h3><p>${esc(e.venue)} · ${esc(e.city)}</p></div><div class="price"><small>From</small>${money(e.price)}</div></div></a>`}
const bannerVisuals={
  'neon-after-midnight':{file:'velora',line1:'Neon After',line2:'Midnight',label:'SYNTHS / LIGHTS / EVERYONE',theme:'neon'},
  'echoes-live-orchestra':{file:'nara',line1:'Echoes:',line2:'Live Orchestra',label:'AN EVENING IN FULL COLOUR',theme:'orchestra'},
  'city-lights-tour':{file:'kairo',line1:'City Lights',line2:'Tour',label:'THE CITY HAS A RHYTHM',theme:'city'},
  'pulse-fest':{file:'pulse',line1:'Pulse',line2:'Fest',label:'ONE SKY. MANY FREQUENCIES.',theme:'festival'},
  'nova-world-tour':{file:'nova',line1:'Nova World',line2:'Tour',label:'SEVEN VOICES. ONE STAGE.',theme:'stadium'},
  'blue-hour':{file:'sora',line1:'Blue',line2:'Hour',label:'AN INTIMATE KIND OF LOUD',theme:'indie'}
};
function bannerCard(e,i){const v=bannerVisuals[e.slug];return `<a class="hero-banner banner-${v.theme}" href="#/event/${esc(e.slug)}" data-slide="${i}" aria-label="Explore ${esc(e.title)} by ${esc(e.artist)}"><img class="banner-image" src="./assets/banners/${v.file}.webp" alt="Concert atmosphere for the fictional ${esc(e.title)} event" ${i===0?'fetchpriority="high"':''}><span class="banner-shade" aria-hidden="true"></span><span class="banner-design"><span class="banner-topline"><span class="banner-brand">TICKETRUE <span class="banner-star">✳</span> LIVE</span><span class="banner-count">0${i+1} / 06</span></span><span class="banner-copy"><span class="banner-kicker">${esc(e.artist)} <i></i> ${esc(e.genre)}</span><span class="banner-title"><span>${v.line1}</span><strong>${v.line2}</strong></span><span class="banner-foot"><span>${esc(date(e.date).toUpperCase())} <i></i> ${esc(e.city.toUpperCase())}</span><span class="banner-tag">${v.label}</span></span><span class="banner-cta">Explore event <span aria-hidden="true">↗</span></span></span></span></a>`}
function motionHero(){const shows=seed.filter(e=>bannerVisuals[e.slug]);return `<section class="hero hero-carousel" aria-label="Featured concerts"><h2 class="sr-only">Featured concerts</h2><div class="carousel-window" id="featured-carousel"><div class="carousel-track">${shows.map(bannerCard).join('')}</div><button class="carousel-arrow carousel-prev" type="button" data-action="carousel-prev" aria-label="Previous concert">‹</button><button class="carousel-arrow carousel-next" type="button" data-action="carousel-next" aria-label="Next concert">›</button><button class="carousel-pause" type="button" data-action="carousel-pause" aria-label="Pause carousel" aria-pressed="false">Ⅱ</button></div></section>`}
// ---- Home: "How it works" with an animated picture for each step ----
function pseudoQr(){const n=13;let s=11;const rnd=()=>((s=(s*1103515245+12345)&0x7fffffff)/0x7fffffff),fin=(r,c,or,oc)=>{const dr=r-or,dc=c-oc;if(dr<0||dc<0||dr>6||dc>6)return null;return dr===0||dr===6||dc===0||dc===6||(dr>=2&&dr<=4&&dc>=2&&dc<=4)};let d='';for(let r=0;r<n;r++)for(let c=0;c<n;c++){const f=fin(r,c,0,0)??fin(r,c,0,n-7)??fin(r,c,n-7,0);const on=f!==null?f:rnd()>.52;if(on)d+=`M${c} ${r}h1v1h-1z`}return `<svg class="hv-qr" viewBox="0 0 ${n} ${n}" shape-rendering="crispEdges"><path d="${d}" fill="#0c2d50"/></svg>`}
function howVisual(kind){
 if(kind==='find'){const rows=seed.slice(0,3).map((e,i)=>`<div class="hv-row${i===0?' hot':''}" style="--r:${i}"><img src="${esc(posterImage(e))}" alt=""><b>${esc(e.title)}</b><small>${esc(date(e.date).slice(0,-5).toUpperCase())}</small></div>`).join('');return `<div class="hv hv-find" aria-hidden="true"><div class="hv-search"><svg viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><span class="hv-type">neon</span></div>${rows}<svg class="hv-cursor" viewBox="0 0 24 24"><path d="M5 3l14 8-6 2-3 6z"/></svg></div>`}
 if(kind==='seat')return `<div class="hv hv-seat" aria-hidden="true"><div class="hv-stage">STAGE</div><div class="hv-seats">${Array.from({length:32},(_,i)=>`<span style="--i:${i}" class="${i===13?'pick':[3,9,18,26,29].includes(i)?'taken':''}"></span>`).join('')}</div><div class="hv-chip"><b>Seat A6</b><small>Rp 450.000</small></div></div>`;
 if(kind==='pass')return `<div class="hv hv-pass" aria-hidden="true"><div class="hv-qrbox">${pseudoQr()}<i class="hv-scan"></i></div><div class="hv-pass-side"><svg class="hv-ring" viewBox="0 0 64 64"><circle cx="32" cy="32" r="26"/><circle class="hv-ring-run" cx="32" cy="32" r="26"/></svg><span class="hv-time">5:00</span><span class="hv-signed">✓ Signed by wallet</span></div></div>`;
 return `<div class="hv hv-resale" aria-hidden="true"><span class="hv-paid">YOU PAID Rp 450.000</span><div class="hv-track"><i class="hv-cap"><em>CAP</em></i><span class="hv-tag bad">Rp 1.350.000</span><span class="hv-tag good">Rp 450.000</span><b class="hv-stamp">CAPPED</b></div><div class="hv-to"><span>you</span><i>→</i><span>fan</span></div></div>`}
const howStep=(n,tag,title,text,cta,href,kind)=>`<a class="how-card" href="${href}" style="--n:${n}">${howVisual(kind)}<span class="how-tag">0${n} / ${tag}</span><h3>${title}</h3><p>${text}</p><span class="how-cta">${cta} <i aria-hidden="true">→</i></span></a>`;
function howSection(){return `<section class="section how" id="how"><div class="container"><div class="how-head"><div><span class="eyebrow">LESS FRICTION. MORE FEELING.</span><h2>From “I'm in”<br>to the front row.</h2></div><p>Four steps. No queue, no scalper markup, and a ticket you can prove is yours.</p></div><div class="how-rail" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="how-steps">${howStep(1,'DISCOVER','Find your night.','Browse six live concerts, filter by city or type, and save your favorites.','Browse concerts','#/discover','find')}${howStep(2,'MAKE IT YOURS','Choose your spot.','Pick a seat on the venue map or a ticket tier, then check out with BOT or the demo.','Try seat selection','#/event/neon-after-midnight','seat')}${howStep(3,'PROVE IT’S YOURS','Show a live pass.','Your ticket lives in your wallet. A QR signed by your wallet proves it is yours, so screenshots stop working.','See My Tickets','#/tickets','pass')}${howStep(4,'PASS IT ON','Resell, fairly.','Can’t go? List it at or below what you paid. The contract keeps scalpers out.','Open Resell','#/resell','resale')}</div></div></section>`}
// ---- Home hero: headline, search, and a 3D ticket that follows the cursor ----
const tkTone={blue:'blue',silver:'silver',amber:'amber',teal:'teal',nova:'nova',dusk:'dusk'};
function tkCard(e,i){const d=new Date(e.date+'T12:00:00'),day=String(d.getDate()).padStart(2,'0'),my=d.toLocaleDateString('en-GB',{month:'long',year:'numeric'}),dow=d.toLocaleDateString('en-GB',{weekday:'long'});return `<article class="tk-card tone-${tkTone[e.color]||'blue'}" data-i="${i}" aria-label="${esc(e.title)}"><div class="tk-tilt"><div class="tk-face"><i class="tk-c1"></i><i class="tk-c2"></i><i class="tk-glare"></i></div><span class="tk-chip">${e.mode==='seat'?'Seat selection':'Ticket tiers'}</span><div class="tk-date"><b>${day}</b><span>${esc(my)}</span></div><div class="tk-name"><h3>${esc(e.title)}</h3><p>${esc(e.artist)}</p></div><div class="tk-info"><strong>${esc(dow)}, ${esc(date(e.date))} · ${esc(e.time)} WIB</strong><span>${esc(e.venue)}, ${esc(e.city)}</span></div><div class="tk-foot"><span>From <b>${money(e.price)}</b></span><a class="tk-cta" href="#/event/${esc(e.slug)}">View tickets</a></div></div></article>`}
function homeHero(){const list=events.filter(e=>!e.draft),cities=[...new Set(list.map(e=>e.city))];return `<section class="hero-home" id="hero-home" aria-label="Find and buy concert tickets"><div class="hh-bg" aria-hidden="true"><i class="hh-orb a"></i><i class="hh-orb b"></i><i class="hh-dots"></i></div><div class="container hh-grid"><div class="hh-copy"><span class="eyebrow">ONE PLACE FOR EVERY NIGHT</span><h1>Buy and resell<br>concert tickets<br>in <em>one place.</em></h1><p class="hh-lead">Pick a concert, choose your seat, and check out. Can’t make it? Resell your ticket at a fair price from the same account.</p><form class="hh-search" id="hero-search" role="search"><label class="hh-field hh-q"><span>Event or artist</span><input name="q" type="search" placeholder="Type a concert name" autocomplete="off"></label><label class="hh-field"><span>City</span><select name="city" aria-label="City"><option value="">All cities</option>${cities.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label class="hh-field"><span>Type</span><select name="mode" aria-label="Ticket type"><option value="">All types</option><option value="seat">Seat selection</option><option value="tier">Ticket tiers</option></select></label><button class="hh-go" type="submit"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>Search tickets</button></form><ul class="hh-points"><li>Six live concerts</li><li>Resale never above what you paid</li><li>Tickets you can prove are yours</li></ul></div><div class="hh-stage"><span class="tk-hint" aria-hidden="true">Move your cursor over the ticket ✦</span><div class="tk-scene" id="tk-scene" role="group" aria-roledescription="carousel" aria-label="Featured concerts">${list.map(tkCard).join('')}<i class="tk-shadow" aria-hidden="true"></i></div><div class="tk-controls"><button type="button" class="tk-arrow" data-tk-prev aria-label="Previous concert">‹</button><div class="tk-dots">${list.map((e,i)=>`<button type="button" data-tk-dot="${i}" aria-label="Show ${esc(e.title)}"></button>`).join('')}</div><button type="button" class="tk-arrow" data-tk-next aria-label="Next concert">›</button></div><p class="sr-only" id="tk-live" aria-live="polite"></p></div></div></section>`}
function home(){return `${homeHero()}<div class="container"><section class="section" id="concerts"><div class="section-title row"><div><span class="eyebrow">FIND YOUR FREQUENCY</span><h2>Good nights start here.</h2><p>Six stages. A thousand ways to feel something.</p></div><a href="#/discover">All concerts &nbsp; ↗</a></div><div class="grid">${events.filter(e=>!e.draft).slice(0,3).map(card).join('')}</div></section></div>${howSection()}<section class="container section editorial"><div class="editorial-image"><img src="./assets/hero.webp" alt="Crowd gathering beneath concert lights" loading="lazy"></div><div><span class="eyebrow">MORE THAN AN ENTRY PASS</span><h2>A great night.<br>A ticket that's<br><em>truly yours.</em></h2><p>Your ticket holds more than a seat number. On-chain ownership makes it possible to verify who it belongs to, long after the last encore.</p><a class="btn secondary" href="#/about">Meet Ticketrue <span>↗</span></a></div></section><section class="container section" style="padding-top:0"><div class="section-title row"><div><span class="eyebrow">KEEP YOUR CALENDAR OPEN</span><h2>More nights to remember.</h2></div><a href="#/discover">Explore lineup ↗</a></div><div class="grid">${events.filter(e=>!e.draft).slice(3,6).map(card).join('')}</div><div class="live-chain" id="live-chain" hidden><div class="live-head"><i class="live-dot" aria-hidden="true"></i><span class="eyebrow">LIVE ON BOT CHAIN</span></div><div class="live-body"><div class="live-count"><strong id="live-count">0</strong><small>tickets issued</small></div><ol class="live-list" id="live-list"></ol></div><a class="live-contract" href="${chainConfig.blockExplorerUrls[0]}/address/${contractAddress}" target="_blank" rel="noreferrer">Contract ${short(contractAddress)} ↗</a></div><div class="chain-band"><div><h3>Big on the experience. Built on trust.</h3><p>Fictional events. Demo Indonesian payments. A real connection to MetaMask.</p></div><a class="chain-name" href="https://botchain.ai" target="_blank" rel="noreferrer">◈ BOT CHAIN ↗</a></div></section>`}
function discover(){return `${motionHero()}<section class="container page discover-page"><span class="eyebrow">THE LIVE COLLECTION / 2026—27</span><h1>Find your next night.</h1><p class="muted">Choose the sound. We'll help you find your spot.</p><div class="filters"><input id="search" type="search" value="${esc(searchQuery)}" placeholder="Search concerts, artists, or cities…" aria-label="Search concerts"><select id="mode-filter" aria-label="Ticket mode"><option value="">All ticket types</option><option value="seat"${searchMode==='seat'?' selected':''}>Seat selection</option><option value="tier"${searchMode==='tier'?' selected':''}>Ticket tiers</option></select><select id="venue-filter" aria-label="Venue"><option value="">All venues</option>${events.map(e=>`<option>${esc(e.venue)}</option>`).join('')}</select><select id="date-filter" aria-label="Month"><option value="">All dates</option><option value="2026-11">November 2026</option><option value="2026-12">December 2026</option><option value="2027-01">January 2027</option></select></div><div class="filter-chip" id="city-chip"${searchCity?'':' hidden'}>City: <b>${esc(searchCity)}</b><button type="button" data-action="clear-city" aria-label="Remove city filter">×</button></div><div class="row" style="margin-bottom:25px"><small id="result-count">${events.filter(e=>!e.draft).length} upcoming concerts</small><small>All events are fictional</small></div><div class="grid" id="results">${events.filter(e=>!e.draft).map(card).join('')}</div></section>`}
function filterEvents(){const q=$('#search').value.toLowerCase(),mode=$('#mode-filter').value,v=$('#venue-filter').value,d=$('#date-filter').value;const list=events.filter(e=>!e.draft&&(!mode||e.mode===mode)&&(!v||e.venue===v)&&(!d||e.date.startsWith(d))&&(!searchCity||e.city===searchCity)&&[e.title,e.artist,e.city].join(' ').toLowerCase().includes(q));$('#result-count').textContent=list.length+' upcoming concerts';{const chip=$('#city-chip');if(chip){chip.hidden=!searchCity;const b=chip.querySelector('b');if(b)b.textContent=searchCity}}$('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>No concerts found.</h2><p>Try a different artist, date, or ticket type.</p><button class="btn secondary" data-action="reset-filters">Clear filters</button></div>'}
const seatZones=[{name:'CAT 2 · Back',key:'back',add:0,rows:['A','B']},{name:'CAT 1 · Left / Right',key:'side',add:150000,rows:['C','D']},{name:'VIP · Front',key:'front',add:300000,rows:['E','F']}];
function seatDetails(e,s){const zone=seatZones.find(x=>x.rows.includes(s[0]));return{zone:zone.name,price:e.price+zone.add}}
function venueSeats(e){
  const seats=(row,start=1,end=10)=>Array.from({length:end-start+1},(_,i)=>{const n=start+i,seat=row+n,info=seatDetails(e,seat),taken=blockedSeat(e,seat);return `<button class="venue-seat zone-${seatZones.find(z=>z.rows.includes(row)).key} ${order?.seat===seat?'selected':''}" data-seat="${seat}" data-event="${e.id}" ${taken?'disabled':''} title="${info.zone} · Seat ${seat} · ${money(info.price)}" aria-label="${info.zone}, seat ${seat}, ${money(info.price)}${taken?', unavailable':''}" aria-pressed="${order?.seat===seat}">${n}</button>`}).join('');
  const front=`<section class="venue-section zone-front" aria-label="VIP front seats"><div class="venue-section-heading"><strong>VIP FRONT</strong><span>Closest to the stage</span></div><div class="venue-seat-row"><span>F</span><div class="venue-seat-grid">${seats('F')}</div></div><div class="venue-seat-row"><span>E</span><div class="venue-seat-grid">${seats('E')}</div></div></section>`;
  const side=direction=>{const start=direction==='left'?1:6,end=start+4;return `<section class="venue-section zone-side" aria-label="CAT 1 ${direction} seats"><div class="venue-section-heading"><strong>CAT 1 · ${direction.toUpperCase()}</strong></div><div class="venue-seat-row"><span>D</span><div class="venue-seat-grid">${seats('D',start,end)}</div></div><div class="venue-seat-row"><span>C</span><div class="venue-seat-grid">${seats('C',start,end)}</div></div></section>`};
  const back=`<section class="venue-section zone-back" aria-label="CAT 2 back seats"><div class="venue-section-heading"><strong>CAT 2 · BACK</strong><span>Rear of the venue</span></div><div class="venue-seat-row"><span>B</span><div class="venue-seat-grid">${seats('B')}</div></div><div class="venue-seat-row"><span>A</span><div class="venue-seat-grid">${seats('A')}</div></div></section>`;
  const prices=seatZones.map(z=>`<div class="venue-price zone-${z.key}"><span class="venue-price-swatch"></span><span><strong>${z.name}</strong><small>${z.key==='front'?'In front of the stage':z.key==='side'?'Same price on both sides':'Farthest from the stage'}</small></span><b>${money(e.price+z.add)}</b></div>`).join('');
  return `<div class="venue-plan-scroll"><div class="venue-plan" role="group" aria-label="Concert venue: stage at the front, three seating prices"><div class="venue-stage-top"><small>PERFORMER AREA</small><strong>STAGE</strong></div><div class="venue-stage-direction">FRONT OF STAGE ↓</div>${front}<div class="venue-sides">${side('left')}<div class="venue-aisle">AISLE</div>${side('right')}</div>${back}<div class="venue-back-label">← ENTRANCE · BACK OF VENUE →</div></div></div><div class="venue-prices"><h4>Three zones. Three prices.</h4>${prices}</div><div class="legend venue-legend"><span><i class="front"></i> VIP front</span><span><i class="side"></i> CAT 1 left & right</span><span><i class="back"></i> CAT 2 back</span><span><i class="yellow"></i> Selected</span><span><i class="unavailable"></i> Taken</span></div>`;
}
function blockedSeat(e,s){const c=chainAvail[e.id];if(c?.live&&c.taken)return c.taken.has(s);return ['A3','A4','B7','B8','C2','D9','E5'].includes(s)||tickets.some(t=>t.eventId===e.id&&t.seat===s)}
function selectorBlock(e){return `<div class="selector${isOff(e)?" is-off":""}" data-tour="selector"${isOff(e)?" inert":""}><div class="row"><h3>${e.mode==='seat'?'Find your seat.':'Choose your experience.'}</h3><small data-tour="availability">${chainAvail[e.id]?.live?'Live from BOT Chain':(e.mode==='seat'?(53-tickets.filter(t=>t.eventId===e.id&&t.seat).length)+' seats':'Tickets')+' available'}</small></div>${e.mode==='seat'?venueSeats(e):e.tiers.map((t,i)=>`<button class="tier ${order?.tier===t?'selected':''}" data-tier="${i}" data-event="${e.id}" ${chainAvail[e.id]?.live&&chainAvail[e.id].tiers?.[i]?.remaining===0n?'disabled':''} aria-pressed="${order?.tier===t}"><span><strong>${esc(t)}</strong><small>${i===0?'Standard entry':i===1?'Closer to the stage':'Priority entry · Premium viewing'} · ${chainAvail[e.id]?.live?(chainAvail[e.id].tiers?.[i]?chainAvail[e.id].tiers[i].remaining+' left on-chain':'not on-chain yet'):(80-i*17)+' available'}</small></span><b>${money(e.price+i*250000)}</b></button>`).join('')}<div class="selection-summary row" id="selection-summary"><span>${order?esc(order.seat?order.tier+' · Seat '+order.seat:order.tier):'Select '+(e.mode==='seat'?'a seat':'a ticket tier')}</span><strong>${order?money(order.price):'—'}</strong></div><button class="btn full" data-action="checkout" ${!order?'disabled':''}>Continue to checkout <span>→</span></button><p class="ownership-note" data-tour="ownership">One wallet can hold one ticket for this event.</p></div>`}
function detail(e){if(!e||e.draft)return missing();if(order?.eventId!==e.id)order=null;return `<section class="container page"><a class="back" href="#/discover">← Back to concerts</a><div class="detail-grid"><div class="detail-art">${poster(e)}<div class="spacer"><span class="eyebrow">THE EXPERIENCE</span><p class="muted spacer">${esc(e.description)}</p><div class="facts"><div><dt>DOORS OPEN</dt><dd>One hour before showtime</dd></div><div><dt>EVENT FORMAT</dt><dd>Fictional concert · All ages</dd></div></div></div></div><div class="detail-copy" data-tour="event"><span class="eyebrow">${esc(e.genre)}</span><h1>${esc(e.title)}</h1><p>Live with ${esc(e.artist)}</p><div class="detail-status"><span class="stock-slot" data-stock="${e.id}">${stockBadge(e)}</span><button type="button" class="btn secondary save-btn${saved.includes(e.id)?" on":""}" data-action="save" data-event="${e.id}" aria-pressed="${saved.includes(e.id)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.5s-7.5-4.6-7.5-10A4.3 4.3 0 0 1 12 7.8a4.3 4.3 0 0 1 7.5 2.7c0 5.4-7.5 10-7.5 10Z"/></svg><span class="save-label">${saved.includes(e.id)?"Saved":"Save"}</span></button></div><dl class="facts"><div><dt>DATE & TIME</dt><dd>${date(e.date)} · ${e.time} WIB</dd></div><div><dt>VENUE</dt><dd>${esc(e.venue)}, ${esc(e.city)}</dd></div></dl>${waitlistBox(e)}${selectorBlock(e)}<div id="resale-market" class="resale-market" hidden></div></div></div>${eventGuide(e)}</section>`}
function selectTicket(e,data){order={eventId:e.id,...data};paid=false;$$('.venue-seat,.tier').forEach(b=>{const active=data.seat?b.dataset.seat===data.seat:b.dataset.tier===String(data.tierIndex);b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)});$('#selection-summary').innerHTML=`<span>${esc(data.seat?data.tier+' · Seat '+data.seat:data.tier)}</span><strong>${money(data.price)}</strong>`;$('[data-action=checkout]').disabled=false}
function login(signup=false){return `<section class="login-page"><svg class="login-curve-defs" width="0" height="0" aria-hidden="true" focusable="false"><defs><clipPath id="login-organic-curve" clipPathUnits="objectBoundingBox"><path d="M0,0 H.384 C.384,.205 .566,.34 .619,.535 C.677,.751 .602,.883 .547,1 H0 Z"/></clipPath></defs></svg><div class="login-shell"><div class="login-visual" aria-hidden="true"></div><div class="login-art"><div class="login-brand">${brand()}</div><div id="login-ticket-stage" class="login-ticket-stage"><article class="login-ticket-fallback"><span>TICKETRUE / LIVE EXPERIENCES</span><h2>YOUR NEXT<br>GREAT NIGHT.</h2><div><span>ADMIT ONE</span><strong>01 / VIP</strong></div><small>CONCERT TICKET · DEMO PREVIEW</small></article></div><button class="login-animation-toggle" data-action="toggle-login-animation" aria-pressed="false" hidden>Pause animation</button></div><div class="login-form"><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h1>${signup?'Make it yours.':'Welcome back.'}</h1><p>${signup?'Create a local demo profile to explore Ticketrue.':'Your next unforgettable night is waiting.'}</p><form id="login-form">${signup?'<label>Full name<input name="name" placeholder="Your name" required maxlength="60" autocomplete="name"></label>':''}<label>Email address<input type="email" name="email" placeholder="you@example.com" required autocomplete="email"></label><label>Password<input type="password" name="password" placeholder="Enter a demo password" required minlength="6" autocomplete="off"></label><div class="row"><label class="remember"><input type="checkbox" name="remember"> Remember me</label><a href="#/forgot">Forgot password?</a></div><button class="btn full" type="submit">${signup?'Create demo account':'Log in'} <span>↗</span></button></form><p class="login-help">${signup?'Already have an account? <a href="#/login">Log in</a>':'New to Ticketrue? <a href="#/signup">Create an account</a>'}</p><div class="divider">OR EXPLORE FIRST</div><button class="btn secondary full" data-action="demo-login">Try the demo</button><p class="login-help muted">Demo sign-in only. Use sample details.<br>No password is stored or sent.</p></div></div></section>`}
async function loadLoginScene(){const container=$('#login-ticket-stage'),version=loginSceneVersion;if(!container)return;try{const {mountLoginTicket}=await import('./login-ticket.js');if(!container.isConnected||version!==loginSceneVersion)return;const instance=mountLoginTicket(container);if(!container.isConnected||version!==loginSceneVersion){instance.dispose();return}loginScene=instance;const toggle=$('.login-animation-toggle');if(toggle){toggle.hidden=false;toggle.textContent=instance.paused?'Play animation':'Pause animation';toggle.setAttribute('aria-pressed',String(instance.paused))}}catch{if(container.isConnected)container.classList.add('static-ticket')}}
function loginSuccess(name,email,remember){user={name,email};if(remember){save('user',user);sessionStorage.removeItem('tr2:user')}else{localStorage.removeItem('tr2:user');sessionStorage.setItem('tr2:user',JSON.stringify(user))}go(returnTo);if(!read('tour:global',false))setTimeout(welcome,150)}
function welcome(){dialog(`<span class="eyebrow">A LITTLE GUIDANCE. A GREAT NIGHT.</span><h2 class="spacer">Welcome to Ticketrue.</h2><p>Discover concerts, choose your ticket, and learn how ownership on BOT Chain works.</p><div class="actions"><button class="btn" data-action="start-tour">Start quick tour →</button><button class="text-button" data-action="skip-global">Skip for now</button></div><p class="spacer" style="font-size:12px">Replay this tutorial anytime from Profile.</p>`)}
const tours={global:[['nav','Everything starts here.','Explore concerts, check your tickets, or open your profile.'],['discover','Find your next concert.','Browse upcoming concerts and filter by artist, venue, or ticket type.'],['tickets','Your tickets live here.','Find your ticket details and any on-chain verification in My Tickets.'],['wallet','Connect when you’re ready.','Approve a connection in MetaMask. Ticketrue never asks for your Secret Recovery Phrase.'],['chain','Ownership you can check.','BOT Chain records ownership when a configured contract transaction is confirmed. Demo tickets are clearly marked.'],['discover','You’re ready.','Pick a concert. We’ll guide you through the rest.']],event:[['event','Meet the show.','Check the artist, date, venue, and opening time.'],['selector','Find your spot.','Choose one available seat or one ticket tier.'],['availability','Check availability.','Unavailable seats cannot be selected. Final inventory is checked again at issuance.'],['ownership','One wallet. One ticket.','A wallet can own one ticket for each event.']],seat:[['selector','The stage is at the top.','Inspect rows A–F. Blue seats are available; dark seats are unavailable.'],['selector','Choose your seat.','Tap a blue seat. Your selection turns yellow and the price updates.'],['selector','Ready for checkout.','Only one seat can be selected. Continue when your seat looks right.']],tier:[['selector','Pick your experience.','Compare viewing areas, entry benefits, and prices.'],['availability','Availability matters.','Each tier has limited inventory. One wallet can hold one ticket per concert.'],['selector','Continue when ready.','Select a tier and review the total before checkout.']],checkout:[['summary','Your order, at a glance.','Confirm your concert, date, seat or tier, and total.'],['payment','Indonesian payment demo.','QRIS, bank, and e-wallet are simulations. No real money moves.'],['payment','The BOT Chain path.','MetaMask can issue a real ticket after the contract is configured. Never approve a transaction you don’t recognize.'],['payment','A clear final step.','A local demo ticket is not on-chain verified. A real ticket appears only after confirmation.']],tickets:[['ticket-list','All your nights, together.','Your local demo tickets stay on this device. Connect your wallet to load on-chain tickets.'],['ticket-list','Check the details.','Open a ticket to see the owner, ticket identifier, and verification state.'],['ticket-list','Verify before you go.','Real tickets include a transaction hash and explorer link. Demo QR previews are not admission passes.']]};
function startTour(key){close();tour={key,index:0};drawTour()}
function drawTour(){ $$('.tour-focus').forEach(e=>e.classList.remove('tour-focus'));const steps=tours[tour.key],step=steps[tour.index],target=$(`[data-tour="${step[0]}"]`);if(target&&target.getBoundingClientRect().width){target.classList.add('tour-focus');target.scrollIntoView({block:'center',behavior:'smooth'})}$('#tour-root').innerHTML=`<div class="tour-shade"></div><aside class="tour-card" role="dialog" aria-label="Quick tour" aria-modal="true"><div class="row"><small>${tour.index+1} OF ${steps.length}</small><button class="text-button" data-action="tour-skip">Skip</button></div><h3>${step[1]}</h3><p>${step[2]}</p><div class="row"><button class="text-button" data-action="tour-back" ${tour.index===0?'disabled':''}>← Back</button><button class="btn small" data-action="tour-next">${tour.index===steps.length-1?'Done ✓':'Next →'}</button></div></aside>`;$('[data-action=tour-next]').focus()}
function endTour(){if(tour)save('tour:'+tour.key,true);tour=null;$('#tour-root').innerHTML='';$$('.tour-focus').forEach(e=>e.classList.remove('tour-focus'))}
function contextTour(key){const origin=path();if(user&&!read('tour:'+key,false)&&!tour&&!$('#modal').open)setTimeout(()=>{if(path()===origin&&!tour&&!$('#modal').open)startTour(key)},450)}
function checkout(){if(!order)return `<section class="container page empty"><h1>Find your ticket first.</h1><p>Choose a seat or ticket tier to start checkout.</p><a class="btn" href="#/discover">Explore concerts →</a></section>`;const e=eventBy(order.eventId);return `<section class="container page"><a class="back" href="#/event/${e.slug}">← Back to your concert</a><span class="eyebrow" style="display:block">ONE STEP CLOSER</span><h1>Make the night yours.</h1><div class="checkout-grid"><div class="panel" data-tour="payment"><h2>Choose how to pay.</h2><div class="payment-tabs"><button class="${payType==='bot'?'active':''}" data-pay-type="bot">BOT Chain · On-chain</button><button class="${payType==='indonesia'?'active':''}" data-pay-type="indonesia">Demo · No chain</button></div><div id="payment-content">${paymentContent()}</div></div><aside class="panel" data-tour="summary"><img class="summary-image" src="${esc(posterImage(e))}" alt="Artwork for ${esc(e.title)}"><span class="eyebrow">YOUR NIGHT</span><h2 class="spacer">${esc(e.title)}</h2><p class="muted">${esc(e.artist)}</p><div class="summary-list"><div><span>Date</span><span>${date(e.date)}</span></div><div><span>Venue</span><span>${esc(e.venue)}</span></div><div><span>${order.seat?'Zone / seat':'Ticket tier'}</span><strong>${esc(order.seat?order.tier+' · '+order.seat:order.tier)}</strong></div><div><span>Ticket</span><span>${money(order.price)}</span></div><div><span>Service fee</span><span>Rp 0</span></div><div><span>Total</span><strong>${money(order.price)}</strong></div></div><p class="notice">One wallet, one ticket per concert. All listed concerts are fictional.</p></aside></div></section>`}
function paymentContent(){if(paid)return `<span class="status demo">DEMO PAYMENT CONFIRMED</span><h3 class="spacer">Your payment simulation is complete.</h3><p class="muted spacer">One final step: choose how to issue your ticket.</p><div class="stack spacer"><button class="btn" data-action="issue-demo">Issue local demo ticket →</button><button class="btn secondary" data-action="issue-real">Connect MetaMask & issue on-chain</button><p class="notice">Local demo tickets are not recorded on BOT Chain. ${contractAddress?'Real issuance requires wallet approval.':'The real contract address is not configured yet.'}</p></div><div id="transaction-state" role="status"></div>`;
if(payType==='bot')return `<div class="payment-body"><span class="status">${esc(chainConfig.chainName.toUpperCase())}</span><h3 class="spacer">Your wallet. Your ticket.</h3><p class="muted spacer">The ticket is issued straight to your wallet by the Ticketrue contract. Anyone can check it on the explorer.</p><div id="chain-quote" class="notice spacer">${contractAddress?'Reading the on-chain price…':'Real payment is unavailable until a deployed contract address is configured. No transaction will be requested.'}</div><div class="stack spacer"><button class="btn secondary" data-action="wallet">${wallet?esc(short(wallet)):'Connect MetaMask'}</button><button class="btn" data-action="issue-real">Buy on BOT Chain →</button><button class="btn secondary" data-action="issue-claim">No BOT yet? Claim a free testnet ticket</button></div><p class="notice spacer">Need testnet BOT? <a href="${botLinks.faucet}" target="_blank" rel="noreferrer">Open the faucet ↗</a></p><div id="transaction-state" role="status"></div></div>`;
return `<div class="methods"><button class="${payment==='qris'?'active':''}" data-payment="qris">▦ QRIS</button><button class="${payment==='bank'?'active':''}" data-payment="bank">▤ Bank / VA</button><button class="${payment==='ewallet'?'active':''}" data-payment="ewallet">▣ E-wallet</button></div><div class="payment-body"><span class="status demo">DEMO PAYMENT · NO REAL MONEY</span>${payment==='qris'?`<div class="qr" aria-label="Non-scannable demo QR pattern">${Array.from({length:169},(_,i)=>`<b class="${(i*7+Math.floor(i/13)*3)%5<3?'on':''}"></b>`).join('')}</div><p style="text-align:center;font-size:12px" class="muted">Demo QR preview · <span id="countdown">60</span>s remaining<br>Do not scan or transfer money.</p>`:payment==='bank'?`<label class="spacer">Choose bank<select id="payment-provider"><option>BCA</option><option>BNI</option><option>BRI</option><option>Mandiri</option></select></label><div class="notice spacer row"><span>DEMO-VA-0000-1234</span><button class="text-button" data-action="copy-va">Copy</button></div><small>This reference is deliberately not a valid bank account.</small>`:`<label class="spacer">Choose e-wallet<select id="payment-provider"><option>GoPay</option><option>DANA</option><option>OVO</option><option>ShopeePay</option></select></label><p class="notice spacer">Demo phone: 08xx-xxxx-0000<br>No e-wallet app will be opened or charged.</p>`}</div><button class="btn full" data-action="simulate">Simulate payment success <span>→</span></button><p class="ownership-note">Hackathon simulation — no real payment is processed.</p>`}
function startCountdown(){clearInterval(timer);if(!$('#countdown'))return;let n=60;timer=setInterval(()=>{if(!$('#countdown')){clearInterval(timer);return}$('#countdown').textContent=--n;if(n<=0){clearInterval(timer);$('#payment-content').innerHTML='<h3>Demo payment expired.</h3><p class="muted spacer">Your selection is still saved.</p><button class="btn spacer" data-action="retry-payment">Generate new demo payment</button>'}},1000)}
function paymentRender(){ $('#payment-content').innerHTML=paymentContent();enhanceSelects($('#payment-content'));startCountdown() }
function ownTickets(){return tickets.filter(t=>t.demo?t.profile===user?.email:wallet&&t.owner.toLowerCase()===wallet.toLowerCase())}
function ticketsPage(){const list=ownTickets();return `<section class="container page"><div class="row"><div><span class="eyebrow">THE NIGHTS YOU'RE PART OF</span><h1>My tickets.</h1></div><button class="btn secondary" data-action="sync-tickets">${wallet?'Refresh on-chain tickets':'Connect wallet'}</button></div><div data-tour="ticket-list" class="tickets-list">${list.length?list.map(t=>{const e=eventBy(t.eventId);return `<article class="ticket-item"><img src="${esc(posterImage(e))}" alt="Artwork for ${esc(e?.title||'concert')}"><div><span class="status ${t.demo?'demo':''}">${t.demo?'LOCAL DEMO · NOT ON-CHAIN':'ON-CHAIN TICKET'}</span><h2>${esc(e?.title||'Concert')}</h2><p>${e?date(e.date):''} · ${esc(e?.venue)}<br>${esc(t.seat?'Seat '+t.seat:t.tier)}</p></div><a class="btn secondary" href="#/tickets/${t.id}">View ticket ↗</a></article>`}).join(''):`<div class="empty"><span style="font-size:50px;color:#5483b3">⌁</span><h2>No tickets yet.</h2><p>Your next unforgettable night can start here.</p><a class="btn" href="#/discover">Explore concerts →</a></div>`}</div>${saveLists()}</section>`}
function ticketPage(id){const t=ownTickets().find(t=>String(t.id)===id);if(!t)return missing();const e=eventBy(t.eventId);return `<section class="container page"><a class="back" href="#/tickets">← My tickets</a><article class="ticket-detail"><div class="ticket-top"><div class="row">${brand()}<span class="status ${t.demo?'demo':''}">${t.demo?'LOCAL DEMO':'ON-CHAIN'}</span></div><p class="eyebrow spacer">ADMIT ONE / ${esc(e.artist)}</p><h1>${esc(e.title)}</h1><p>${date(e.date)} · ${e.time} WIB</p></div><div class="ticket-bottom"><dl><div><dt>VENUE</dt><dd>${esc(e.venue)}</dd></div><div><dt>${t.seat?'SEAT':'TIER'}</dt><dd>${esc(t.seat||t.tier)}</dd></div><div><dt>TICKET ID</dt><dd>${esc(t.id)}</dd></div><div><dt>OWNER</dt><dd>${esc(t.owner)}</dd></div><div><dt>ISSUED</dt><dd>${new Date(t.issuedAt).toLocaleString()}</dd></div><div><dt>STATUS</dt><dd>${t.demo?'Demo only · Not valid for admission':'Recorded on BOT Chain'+(t.used?' · Used at gate':'')}</dd></div></dl>${t.tx?`<p class="code">${esc(t.tx)}</p><a href="${chainConfig.blockExplorerUrls[0]}/tx/${t.tx}" target="_blank" rel="noreferrer">View transaction on explorer ↗</a>`:'<p style="font-size:13px">No blockchain transaction exists for this local demo ticket.</p>'}<div id="pass-box" class="pass-box spacer"></div>${t.demo?'':`<div class="resale-box spacer" data-resale-for="${esc(t.id)}">Checking BOT Chain…</div>`}<div class="actions spacer">${t.demo?'<a class="btn" href="#/discover">Get an on-chain ticket →</a>':`<button class="btn" data-verify="${t.id}">Verify on BOT Chain</button>`}<button class="btn secondary" style="color:#052659;border-color:#5483b3" data-action="preview-machine">Preview ticket reveal</button><button class="btn secondary" style="color:#052659;border-color:#5483b3" data-action="cal-add" data-ticket="${esc(t.id)}">Add to calendar</button><button class="btn secondary" style="color:#052659;border-color:#5483b3" data-action="share-ticket" data-ticket="${esc(t.id)}">Share</button><button class="btn secondary" style="color:#052659;border-color:#5483b3" data-action="dl-ticket" data-ticket="${esc(t.id)}">Download ticket</button></div><div id="verify-result" class="spacer"></div></div></article></section>`}
async function issueDemo(){if(busy)return;{const ev=eventBy(order?.eventId);if(ev&&isOff(ev))throw Error('This concert is not available right now.')}if(!user){returnTo='/checkout';go('/login');return}const e=eventBy(order?.eventId);if(!e||!paid)throw Error('Complete a demo payment first.');const owner=wallet||('demo:'+user.email);if(tickets.some(t=>t.eventId===e.id&&t.owner.toLowerCase()===owner.toLowerCase()))throw Error('This wallet already owns a ticket for this concert.');if(order.seat&&blockedSeat(e,order.seat))throw Error('That seat was just taken. Please choose another.');const t={...order,id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),owner,profile:user.email,issuedAt:new Date().toISOString(),demo:true};tickets.push(t);save('tickets',tickets);order=null;paid=false;go('/reveal/'+t.id)}
async function issueReal(free=false){if(busy)return;if(!order)throw Error('Choose a seat or ticket tier first.');if(!contractAddress)throw Error('The BOT Chain contract is not configured yet. Use the clearly labeled local demo path.');busy=true;const current={...order};try{await connectWallet();const result=await web3.issueTicket(current,{fiatDemo:paid||free,status:msg=>{$('#transaction-state').innerHTML='<p class="notice spacer">'+esc(msg)+'</p>'}});const t={...current,...result,owner:wallet,profile:user?.email,demo:false,issuedAt:new Date().toISOString()};tickets.push(t);save('tickets',tickets);order=null;paid=false;delete chainAvail[current.eventId];go('/reveal/'+t.id)}finally{busy=false}}
function reveal(id,preview=false){const t=tickets.find(t=>t.id===id);return `<section class="container page machine-page"><span class="eyebrow">${preview?'CINEMATIC PREVIEW':t?.demo?'LOCAL DEMO EXPERIENCE':'OWNERSHIP CONFIRMED'}</span><h1>${preview?'A little magic before the music.':'This night is yours.'}</h1><p>${t?.demo||preview?'A preview of the ticket reveal. No on-chain transaction is implied.':'Your ticket ownership is recorded on BOT Chain.'}</p><div class="machine-stage" id="machine-stage"><div id="machine-fallback" class="fallback-ticket"><span>TICKETRUE / ${t?.demo||preview?'DEMO':'VERIFIED'}</span><strong>${esc(eventBy(t?.eventId)?.title||'YOUR NEXT NIGHT')}</strong><hr><span>ONE TICKET. ONE UNFORGETTABLE NIGHT.</span></div></div><p id="machine-caption">Preparing the ticket machine…</p><a class="btn spacer" href="${t?'#/tickets/'+t.id:'#/discover'}">${t?'Reveal my ticket':'Explore concerts'} →</a></section>`}
async function loadMachine(){const container=$('#machine-stage');if(!container)return;try{if(matchMedia('(prefers-reduced-motion: reduce)').matches)throw Error('Reduced motion');const {mountMachine}=await import('./machine.js');const instance=await mountMachine(container);if(!container.isConnected){instance.dispose();return}machine=instance;$('#machine-caption').textContent='Your ticket is printing…';setTimeout(()=>{if(machine===instance)instance.print()},900);setTimeout(()=>{if($('#machine-caption'))$('#machine-caption').textContent='Ready for your next unforgettable night.'},4500)}catch{if($('#machine-caption'))$('#machine-caption').textContent='Your ticket is ready.'}}
function profile(){return `<section class="container page"><span class="eyebrow">YOUR TICKETRUE</span><h1>Hello, ${esc(user.name.split(' ')[0])}.</h1><div class="profile-grid"><div class="panel"><h2>Your profile</h2><p>${esc(user.name)}</p><p class="muted">${esc(user.email)}</p><p class="notice spacer">Local demo profile. This is not a production authentication account.</p><div class="settings-row"><div>Wallet<p>${wallet?esc(short(wallet)):'Not connected'}</p></div><button class="text-button" data-action="wallet">${wallet?'Manage':'Connect'} ↗</button></div><button class="text-button spacer" data-action="logout">Log out →</button></div><div class="panel"><h2>A little guidance</h2><div class="settings-row"><div>Quick tour<p>Revisit the basics.</p></div><button class="text-button" data-action="replay">Replay →</button></div><div class="settings-row"><div>All feature tutorials<p>See tips when you open each feature.</p></div><button class="text-button" data-action="reset-tours">Reset →</button></div><div class="settings-row"><div>Organizer demo<p>Manage fictional events on this device.</p></div><a class="text-button" href="#/organizer">Open →</a></div><button class="text-button spacer" data-action="preview-machine">Preview the 3D ticket reveal ↗</button></div></div></section>`}
function organizer(){return `<section class="container page"><div class="row"><div><span class="eyebrow">ORGANIZER / LOCAL DEMO</span> <a class="text-button" href="#/dashboard">Sales dashboard ↗</a><h1>Your stages.</h1></div><button class="btn" data-action="new-event">Create event +</button></div><p class="notice">Changes are stored on this device only. Publishing here updates the local catalog; it does not create an on-chain event.</p><div class="stats"><div class="panel"><strong>${events.length}</strong><span>Fictional events</span></div><div class="panel"><strong>${tickets.length}</strong><span>Tickets on this device</span></div><div class="panel"><strong>${tickets.filter(t=>!t.demo).length}</strong><span>On-chain tickets cached</span></div></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Ticket mode</th><th>Status</th><th></th></tr></thead><tbody>${events.map(e=>`<tr><td><strong>${esc(e.title)}</strong><br><small>${esc(e.artist)}</small></td><td>${date(e.date)}</td><td>${e.mode==='seat'?'Seat selection':'Ticket tiers'}</td><td>${e.draft?'Draft':'Published locally'}</td><td><button class="text-button" data-edit-event="${e.id}">Edit ↗</button></td></tr>`).join('')}</tbody></table></div><h2 class="spacer">Ticket activity</h2>${tickets.length?`<div class="table-wrap"><table><thead><tr><th>Ticket</th><th>Event</th><th>Mode</th><th>Issued</th></tr></thead><tbody>${tickets.map(t=>`<tr><td>${esc(t.id)}</td><td>${esc(eventBy(t.eventId)?.title)}</td><td>${t.demo?'Local demo':'On-chain'}</td><td>${new Date(t.issuedAt).toLocaleDateString()}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted spacer">No activity yet. Complete a demo checkout to see ticket issuance here.</p>'}</section>`}
function eventForm(id){const e=id?eventBy(id):{};dialog(`<h2>${id?'Edit':'Create'} event</h2><form class="stack" id="event-form" data-id="${id||''}"><label>Concert name<input name="title" value="${esc(e.title||'')}" required maxlength="70"></label><label>Artist<input name="artist" value="${esc(e.artist||'')}" required maxlength="60"></label><div class="row"><label>Date<input name="date" type="date" value="${e.date||''}" required></label><label>Starting price (IDR)<input name="price" type="number" value="${e.price||275000}" min="0" max="100000000" required></label></div><label>Venue<input name="venue" value="${esc(e.venue||'')}" required maxlength="80"></label><label>City<input name="city" value="${esc(e.city||'')}" required maxlength="40"></label><label>Ticket mode<select name="mode"><option value="seat" ${e.mode==='seat'?'selected':''}>Seat selection · 6 rows × 10 seats</option><option value="tier" ${e.mode==='tier'?'selected':''}>Ticket tiers</option></select></label><label>Tier names (comma separated)<input name="tiers" value="${esc((e.tiers||['Regular','Premium','VIP']).join(', '))}" required></label><label><input type="checkbox" name="draft" ${e.draft?'checked':''}> Save as draft</label><button class="btn">Save event</button></form>`)}
function aboutChoice(mode='seat'){const seated=mode==='seat';return `<div class="about-choice-preview"><div class="about-choice-visual" aria-hidden="true">${seated?'<div class="about-mini-stage">STAGE</div><div class="about-mini-seats">'+Array.from({length:32},(_,i)=>'<span style="--i:'+i+'" class="'+(i===12?'picked':[3,7,19,25].includes(i)?'taken':'')+'"></span>').join('')+'</div><div class="about-mini-legend"><i></i> Your spot, your choice</div>':'<div class="about-mini-tier"><span>FESTIVAL</span><small>The shared energy</small></div><div class="about-mini-tier picked"><span>VIP</span><small>A little closer to the music</small><b>✓</b></div><div class="about-mini-tier"><span>VVIP</span><small>The full experience</small></div>'}</div><div class="about-choice-copy"><span class="eyebrow">${seated?'EVERY SEAT HAS A STORY':'FIND YOUR KIND OF NIGHT'}</span><h3>${seated?'Your favorite view.':'Your perfect experience.'}</h3><p>${seated?'Choose an available seat, see your price, and make it yours. One wallet holds one ticket per concert.':'Compare entry benefits and viewing areas. Pick the tier that feels right for your night.'}</p><a href="#/event/${seated?'neon-after-midnight':'pulse-fest'}" class="text-button">Try ${seated?'seat selection':'ticket tiers'} ↗</a></div></div>`}
let aboutTimer=null;
const nextNight=()=>{const now=Date.now();return events.filter(e=>!e.draft).map(e=>({e,t:new Date(`${e.date}T${e.time}:00+07:00`).getTime()})).filter(x=>x.t>now).sort((x,y)=>x.t-y.t)[0]||null};
const cdHTML=ms=>{const s=Math.max(0,Math.floor(ms/1000)),p=[Math.floor(s/86400),Math.floor(s%86400/3600),Math.floor(s%3600/60),s%60].map(n=>String(n).padStart(2,'0'));return `<b>${p[0]}</b><i>d</i><b>${p[1]}</b><i>h</i><b>${p[2]}</b><i>m</i><b>${p[3]}</b><i>s</i>`};
const aboutNext=()=>{const n=nextNight();if(!n)return'';const e=n.e;return `<div class="about-next"><span class="about-eq" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><small>NEXT NIGHT</small><strong>${esc(e.title)}</strong><span>${esc(date(e.date).toUpperCase())} · ${esc(e.venue)}</span><div class="about-cd" id="about-countdown" role="timer" aria-label="Time until ${esc(e.title)}">${cdHTML(n.t-Date.now())}</div><a href="#/event/${esc(e.slug)}">Get tickets ↗</a></div>`};
function tickAbout(){const el=$('#about-countdown'),n=nextNight();if(el&&n)el.innerHTML=cdHTML(n.t-Date.now())}
const aboutMarquee=()=>{const g=[...seed,...seed].map(e=>`<span>${esc(e.artist)}</span><i aria-hidden="true">✳</i>`).join('');return `<div class="about-marquee" aria-hidden="true"><div class="about-marquee-track"><div>${g}</div><div>${g}</div></div></div>`};
function about(){return `<section class="about-page"><div class="container about-intro"><div class="about-intro-copy"><span class="eyebrow">THIS IS TICKETRUE</span><h1>For the music.<br>For the moment.<br><em>For you.</em></h1><p>That first note. A room full of strangers singing the same words. We believe getting there should feel just as good.</p><a class="btn" href="#/discover">Find your next night <span>↗</span></a></div><figure class="about-photo"><img src="./assets/hero.webp" alt="Blue concert lights above a crowd gathered for a live show">${aboutNext()}<svg class="about-badge" viewBox="0 0 120 120" aria-hidden="true" focusable="false"><defs><path id="about-ring" d="M60,60 m-44,0 a44,44 0 1,1 88,0 a44,44 0 1,1 -88,0"/></defs><g class="about-ring"><text font-size="10.5" font-weight="700" letter-spacing="2"><textPath href="#about-ring" textLength="272" lengthAdjust="spacing">LIVE ✳ LOUD ✳ TOGETHER ✳ </textPath></text></g><circle cx="60" cy="60" r="27" fill="#F9A12B"/><text x="60" y="67" text-anchor="middle" font-size="24" font-weight="700" fill="#0c2d50">t.</text></svg><figcaption><span>THE CROWD. THE SOUND. THE MOMENT.</span><strong>Be part of it.</strong></figcaption></figure></div>${aboutMarquee()}<div class="about-facts"><div class="container"><div><strong data-count="6" data-pad="2">06</strong><span>Fictional concerts.<br>A whole range of sound.</span></div><div><strong data-count="2" data-pad="2">02</strong><span>Ways to find your spot.<br>Seats or ticket tiers.</span></div><div><strong data-count="1" data-pad="2">01</strong><span>Ticket per wallet.<br>A night that’s yours.</span></div></div></div><section class="container about-choose"><div class="about-heading"><div><span class="eyebrow">A LITTLE CHOICE GOES A LONG WAY</span><h2>How do you like<br>to feel the music?</h2></div><div class="about-switch" role="group" aria-label="Explore ticket types"><button class="active" data-about-mode="seat" aria-pressed="true">Pick a seat</button><button data-about-mode="tier" aria-pressed="false">Pick a tier</button></div></div><div id="about-choice">${aboutChoice()}</div></section><section class="about-trust"><div class="container about-trust-grid"><div class="about-ticket" aria-label="Example local demo ticket"><div class="row"><span class="brand">${icon('ticket')} ticketrue.</span><span class="status demo">DEMO</span></div><span class="eyebrow">ONE NIGHT. ALL THE FEELINGS.</span><h3>NEON AFTER<br>MIDNIGHT</h3><p>VELORA / 14 NOV 2026</p><div class="about-ticket-stub"><div><small>YOUR SEAT</small><strong>A · 01</strong></div><div><small>YOUR MOMENT</small><strong>Admit one</strong></div></div><small>Illustrative demo · Not an admission pass</small></div><div class="about-trust-copy"><span class="eyebrow">MORE THAN A CONFIRMATION EMAIL</span><h2>A ticket you hold.<br><em>Ownership you can check.</em></h2><p>Choose your concert, try a familiar checkout, and keep everything together in My Tickets. QRIS, bank, and e-wallet payments are simulations here.</p><div class="about-proof"><span>${icon('shield')}</span><div><h3>A clearer kind of trust.</h3><p>With a configured contract, BOT Chain records ownership and gives your ticket a transaction you can verify.</p></div></div><p class="notice">${contractAddress?'Contract configured. Check your ticket’s verification details.':'On-chain issuance is not active yet. Local demo tickets are clearly marked and are not blockchain records.'}</p><a class="text-button" href="https://botchain.ai" target="_blank" rel="noreferrer">Meet BOT Chain ↗</a></div></div></section><section class="container about-encore"><div><span class="eyebrow">THE LITTLE DETAILS MATTER</span><h2>Even your ticket<br>gets an <em>entrance.</em></h2><p>A cinematic machine. A ticket that slides into view.<br>A small moment before the big one.</p></div><a class="about-reveal-link" href="#/machine"><span class="about-play" aria-hidden="true">↗</span><span>Preview the 3D reveal<small>Take a look before choosing your concert</small></span></a></section></section>`}

function legal(type){return `<section class="container page prose"><h1>${type==='privacy'?'Your privacy.':'Demo terms.'}</h1>${type==='privacy'?'<p>This prototype stores demo profile details, local ticket records, organizer changes, and tutorial preferences in your browser. Passwords are not stored or transmitted.</p><p>Wallet connection is handled by MetaMask. Ticketrue never asks for recovery phrases or private keys. Actual blockchain transactions are public and must not include personal details.</p><p>To clear local data, log out and clear this site’s browser storage. Generated concert artwork does not depict a real event.</p>':'<p>Ticketrue is a hackathon prototype. All six concerts, artists, venues, inventory counts, and listed prices are fictional. No ticket grants admission to a real event.</p><p>Indonesian payments are simulations. Never transfer money using this demo. Local demo tickets are not blockchain records.</p><p>The optional blockchain path requires a configured contract and your explicit approval in MetaMask. Testnet tokens have no implied monetary value.</p>'}</section>`}
function missing(){return '<section class="container page empty"><h1>This page missed the encore.</h1><p>The event or ticket could not be found.</p><a class="btn" href="#/discover">Back to concerts →</a></section>'}
async function connectWallet(){wallet=await web3.connectWallet();shell();toast('MetaMask connected: '+short(wallet));return wallet}
function walletDialog(){dialog(`<span class="eyebrow">${esc(chainConfig.chainName.toUpperCase())}</span><h2 class="spacer">Connect your wallet.</h2><p>Approve the connection in MetaMask, then switch to ${esc(chainConfig.chainName)} when prompted.</p><p class="notice">Ticketrue will never ask for your Secret Recovery Phrase.</p><div class="stack spacer"><button class="btn" data-action="connect">${wallet?'Reconnect MetaMask':'Connect MetaMask'} ↗</button>${wallet?`<code class="code">${esc(wallet)}</code><button class="text-button" data-action="disconnect">Disconnect in Ticketrue</button>`:''}</div><div id="wallet-error" class="inline-error spacer" role="alert"></div>`)}
const ago=t=>{const s=Math.max(0,Math.round((Date.now()-t)/1000));return s<60?'just now':s<3600?Math.floor(s/60)+'m ago':s<86400?Math.floor(s/3600)+'h ago':Math.floor(s/86400)+'d ago'};
const bot=wei=>{const n=Number(wei)/1e18;return (n>=1?n.toFixed(2):n.toPrecision(4)).replace(/\.?0+$/,'')+' BOT'};
async function loadQuote(){if(!$('#chain-quote')||!contractAddress||!order)return;const snap=order;try{const q=await web3.quote(snap);if(order!==snap||!$('#chain-quote'))return;$('#chain-quote').innerHTML=q.taken?'That seat is already taken on-chain.':q.remaining===0n?'Sold out on-chain.':`<strong>${bot(q.price)}</strong> · ${q.remaining} left on-chain · plus network fee`}catch{if($('#chain-quote'))$('#chain-quote').textContent='This event is not open on-chain yet.'}}
async function loadAvailability(e){if(!contractAddress||!e)return;try{const av=await web3.chainAvailability(e);chainAvail[e.id]=av;if(av.live&&$('.selector')&&eventBy(path().split('/')[2])?.id===e.id)$('.selector').outerHTML=selectorBlock(e)}catch{}}
async function loadLive(){const box=$('#live-chain');if(!box||!contractAddress)return;try{const r=await web3.activity(5);if(!$('#live-chain'))return;box.hidden=false;countTo($('#live-count'),r.issued,{from:parseInt($('#live-count').textContent)||0});$('#live-list').innerHTML=r.items.length?r.items.map(i=>`<li><span>${esc(short(i.owner))}</span><span>${esc(eventBy(i.eventId)?.title||'Event '+i.eventId)}</span><span>${i.at?ago(i.at):''}</span><a href="${chainConfig.blockExplorerUrls[0]}/tx/${esc(i.tx)}" target="_blank" rel="noreferrer" aria-label="View transaction on explorer">↗</a></li>`).join(''):'<li class="live-empty">No tickets yet. Be the first on-chain.</li>'}catch{}}
const toWei=s=>{const v=String(s).trim();if(!/^\d*\.?\d+$/.test(v))throw Error('Enter a valid BOT amount.');const [i,f='']=v.split('.');return BigInt(i||'0')*10n**18n+BigInt((f+'0'.repeat(18)).slice(0,18))};
const txStatus=sel=>msg=>{const el=$(sel);if(el)el.innerHTML='<p class="notice spacer">'+esc(msg)+'</p>'};
async function syncTickets(){const chainTickets=await web3.getWalletTickets();tickets=[...tickets.filter(t=>t.demo||t.owner.toLowerCase()!==wallet.toLowerCase()),...chainTickets.map(t=>({...tickets.find(old=>!old.demo&&old.id===t.id),...t,tier:tierName(eventBy(t.eventId),t.tierIndex)||t.tier}))];save('tickets',tickets)}
async function loadResaleBox(t){const box=$(`[data-resale-for="${t.id}"]`);if(!box||!contractAddress)return;try{const info=await web3.ticketInfo(t.id);let html;if(info.used)html='<strong>Checked in.</strong> This ticket was used at the gate and can no longer be transferred.';else if(info.paid===0n)html='Free claimed tickets can’t be resold. Only tickets that were paid for can be listed.';else if(info.listed>0n)html=`<strong>Listed for ${bot(info.listed)}.</strong> Buyers can see it on the Resell page.<div class="actions spacer"><button class="btn secondary" data-action="resale-cancel" data-ticket="${esc(t.id)}">Cancel listing</button></div>`;else html=`<strong>Resell this ticket.</strong> The price can’t be higher than the ${bot(info.paid)} you paid. 5% goes to the organizer.<form class="row spacer" id="resale-form-${esc(t.id)}" data-resale-form data-ticket="${esc(t.id)}"><input name="price" inputmode="decimal" placeholder="Price in BOT" value="${esc(String(Number(info.paid)/1e18))}" aria-label="Resale price in BOT"><button class="btn secondary">List for resale</button></form>`;box.innerHTML=html+`<div id="resale-state-${esc(t.id)}" role="status"></div>`}catch{}}
async function doResale(id,priceStr){const st='#resale-state-'+id;try{await web3.listForResale(id,toWei(priceStr),txStatus(st));toast('Listed for resale.');await loadResaleBox({id})}catch(err){toast(err.message||'Could not list the ticket.');if($(st))$(st).innerHTML='<p class="notice error spacer">'+esc(err.message||'')+'</p>'}}
const resaleRow=(l,full)=>{const e=eventBy(l.eventId),mine=wallet&&l.owner.toLowerCase()===wallet.toLowerCase();return `<div class="resale-row"><span><strong>${full?esc(e?.title||'Event '+l.eventId)+' · ':''}${esc(l.seat?'Seat '+l.seat:(e?.tiers[l.tierIndex]||'Ticket'))}</strong><small>${full&&e?esc(date(e.date))+' · '+esc(e.city)+' · ':''}Ticket #${esc(l.id)} · seller ${esc(short(l.owner))}</small></span><b>${bot(l.listed)}</b>${mine?'<span class="resale-yours">Your listing</span>':`<button class="btn secondary" data-action="resale-buy" data-ticket="${esc(l.id)}" data-price="${l.listed}">Buy</button>`}</div>`};
async function loadMarket(e){if(!$('#resale-market')||!contractAddress||!e)return;try{const list=await web3.listings(e.id),box=$('#resale-market');if(!box)return;if(!list.length){box.hidden=true;return}box.hidden=false;box.innerHTML='<div class="row"><h3>Verified resale</h3><small>Capped at what the seller paid</small></div>'+list.map(l=>resaleRow(l,false)).join('')+'<div id="market-state" role="status"></div>'}catch{}}
const demoMode=()=>!contractAddress;
const seedListings=()=>[{tid:'DEMO-RS-1',eventId:1,seat:'A6',tier:'CAT 2 · Back',price:420000,paid:450000,seller:'fan.9f3a'},{tid:'DEMO-RS-2',eventId:4,tierIndex:2,tier:'VIP',price:800000,paid:875000,seller:'fan.c71b'},{tid:'DEMO-RS-3',eventId:6,tierIndex:1,tier:'Premium',price:480000,paid:525000,seller:'fan.02de'}];
let listings=read('listings',null);if(!Array.isArray(listings)){listings=seedListings();save('listings',listings)}
const pctOff=(face,price)=>{const p=Math.round((1-Number(price)/Number(face))*100);return p>0?'−'+p+'% vs face':'At face value'};
const tierName=(e,i)=>e?.mode==='seat'?seatZones[i]?.name:e?.tiers?.[i];
const spotOf=(e,x)=>x.seat?((x.tier?x.tier+' · ':'')+'Seat '+x.seat):(x.tier||tierName(e,x.tierIndex)||'Ticket');
const rsCard=x=>{const e=eventBy(x.eventId);return `<article class="rs-ticket"><div class="rs-art"><img src="${esc(posterImage(e))}" alt="" loading="lazy"></div><div class="rs-body"><span class="rs-tag">${esc(x.spot)}</span><h3>${esc(e?.title||'Event '+x.eventId)}</h3><p>${e?esc(e.artist)+' · '+esc(date(e.date))+' · '+esc(e.city):''}</p><small>${esc(x.meta)}</small></div><div class="rs-stub"><small>ASKING</small><strong>${esc(x.price)}</strong><s>Face ${esc(x.face)}</s><span class="rs-save">${esc(x.save)}</span>${x.action}</div></article>`};
const demoCard=l=>{const e=eventBy(l.eventId),mine=tickets.some(t=>t.id===l.tid&&ownTickets().includes(t));return rsCard({eventId:l.eventId,spot:spotOf(e,l),meta:'Listed by '+(mine?'you':l.seller),price:money(l.price),face:money(l.paid),save:pctOff(l.paid,l.price),action:mine?`<button class="btn rs-btn" data-action="demo-sim-sale" data-ticket="${esc(l.tid)}">Simulate a buyer</button><button class="text-button rs-cancel" data-action="demo-resale-cancel" data-ticket="${esc(l.tid)}">Cancel listing</button>`:`<button class="btn rs-btn" data-action="demo-resale-buy" data-ticket="${esc(l.tid)}">Buy ticket</button>`})};
const chainCard=l=>{const e=eventBy(l.eventId),mine=wallet&&l.owner.toLowerCase()===wallet.toLowerCase();return rsCard({eventId:l.eventId,spot:spotOf(e,l),meta:'Ticket #'+l.id+' · seller '+short(l.owner),price:bot(l.listed),face:bot(l.paid),save:pctOff(l.paid,l.listed),action:mine?'<span class="resale-yours">Your listing</span>':`<button class="btn rs-btn" data-action="resale-buy" data-ticket="${esc(l.id)}" data-price="${l.listed}">Buy ticket</button>`})};
const rsMine=(t,body)=>{const e=eventBy(t.eventId);return `<article class="rs-mine"><div class="rs-art"><img src="${esc(posterImage(e))}" alt="" loading="lazy"></div><div class="rs-mine-info"><span class="rs-tag">${esc(spotOf(e,t))}</span><h3>${esc(e?.title||'Concert')}</h3><p>Ticket ${esc(t.id)}${t.demo?' · demo':''}</p></div><div class="rs-mine-act">${body}</div></article>`};
const demoMineBody=t=>{const l=listings.find(x=>x.tid===t.id);if(l)return `<strong>Listed at ${money(l.price)}</strong><small>Waiting for a buyer. Cap: ${money(l.paid)}.</small><div class="rs-acts"><button class="btn secondary" data-action="demo-sim-sale" data-ticket="${esc(t.id)}">Simulate a buyer</button><button class="text-button" data-action="demo-resale-cancel" data-ticket="${esc(t.id)}">Cancel</button></div>`;const p=Number(t.price)||0;return `<form class="rs-form" data-demo-resale data-ticket="${esc(t.id)}" data-cap="${p}"><label for="p-${esc(t.id)}">Your price · max ${money(p)}</label><div class="rs-price"><span>Rp</span><input id="p-${esc(t.id)}" name="price" inputmode="numeric" autocomplete="off" value="${p}"></div><div class="rs-chips"><button type="button" class="chip" data-action="price-chip" data-value="${p}">Face value</button><button type="button" class="chip" data-action="price-chip" data-value="${Math.round(p*.9)}">−10%</button><button type="button" class="chip" data-action="price-chip" data-value="${Math.round(p*.8)}">−20%</button></div><p class="rs-receive" data-receive>You receive ${money(Math.floor(p*.95))} after the 5% organizer share.</p><button class="btn">List for resale</button></form>`};
function updateReceive(f){const cap=Number(f.dataset.cap),v=Number(String(f.elements.price.value).replace(/\D/g,'')),out=f.querySelector('[data-receive]');if(!out)return;out.classList.toggle('over',v>cap);out.textContent=!v?'Enter a price.':v>cap?'That is above the '+money(cap)+' you paid. Lower it to list.':'You receive '+money(Math.floor(v*.95))+' after the 5% organizer share.'}
function demoOwner(){if(!user){returnTo='/resell';go('/login');return null}return wallet||('demo:'+user.email)}
function demoList(tid,raw){const t=tickets.find(x=>x.id===tid&&x.demo);if(!t)throw Error('Ticket not found.');const price=Number(String(raw).replace(/\D/g,''));if(!price)throw Error('Enter a price in Rp.');if(price>t.price)throw Error('The price can’t be higher than the '+money(t.price)+' you paid.');if(listings.some(l=>l.tid===tid))throw Error('This ticket is already listed.');listings.push({tid,eventId:t.eventId,seat:t.seat,tier:t.tier,tierIndex:t.tierIndex,price,paid:t.price,seller:t.owner});save('listings',listings);toast('Listed for '+money(price)+'.');render()}
function demoCancel(tid){listings=listings.filter(l=>l.tid!==tid);save('listings',listings);toast('Listing cancelled.');render()}
function demoSimSale(tid){const l=listings.find(x=>x.tid===tid);if(!l)throw Error('Listing not found.');tickets=tickets.filter(t=>t.id!==tid);listings=listings.filter(x=>x.tid!==tid);save('tickets',tickets);save('listings',listings);toast('Sold for '+money(l.price)+'. You receive '+money(Math.floor(l.price*.95))+' after the 5% organizer share.');render()}
function demoBuy(tid){const l=listings.find(x=>x.tid===tid);if(!l)throw Error('That ticket was just sold.');const owner=demoOwner();if(!owner)return;if(tickets.some(t=>t.eventId===l.eventId&&t.owner.toLowerCase()===owner.toLowerCase()))throw Error('You already hold a ticket for this concert. One ticket per wallet.');if(l.seat&&tickets.some(t=>t.eventId===l.eventId&&t.seat===l.seat))throw Error('That seat is no longer available.');const t={eventId:l.eventId,seat:l.seat,tier:l.tier,tierIndex:l.tierIndex??0,price:l.price,id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),owner,profile:user.email,issuedAt:new Date().toISOString(),demo:true};tickets.push(t);listings=listings.filter(x=>x.tid!==tid);save('tickets',tickets);save('listings',listings);toast('The ticket is yours, bought at '+money(l.price)+'.');go('/tickets/'+t.id)}
function resell(){const demo=demoMode(),mine=ownTickets().filter(t=>!!t.demo===demo),n=demo?listings.length:null;const sell=demo?(!user?'<div class="rs-empty"><strong>Log in to see your tickets.</strong><p>Demo tickets belong to your demo profile.</p><a class="btn" href="#/login">Log in ↗</a></div>':mine.length?mine.map(t=>rsMine(t,demoMineBody(t))).join(''):'<div class="rs-empty"><strong>You have no tickets to sell yet.</strong><p>Buy a demo ticket first, then come back to list it.</p><a class="btn" href="#/discover">Find a concert →</a></div>'):(!wallet?'<div class="rs-empty"><strong>Connect your wallet.</strong><p>We’ll show the tickets you can resell.</p><button class="btn" data-action="wallet">Connect wallet</button></div>':mine.length?mine.map(t=>rsMine(t,`<div class="resale-box" data-resale-for="${esc(t.id)}">Checking BOT Chain…</div>`)).join(''):'<div class="rs-empty"><strong>No on-chain tickets in this wallet.</strong><p>Buy one first, then list it here.</p><a class="btn" href="#/discover">Find a concert →</a></div>');
return `<section class="rs-page"><div class="rs-band"><div class="container rs-hero"><div class="rs-hero-copy"><span class="eyebrow">FAIR RESALE</span><h1>Can’t make it?<br><em>Pass it on, fairly.</em></h1><p>Sell your ticket to another fan without the scalper markup. The price can never go above what you paid.</p>${demo?'<p class="rs-demo"><i></i>DEMO MODE · resale is simulated in this browser and switches to BOT Chain when the contract goes live.</p>':''}<div class="rs-cta"><button class="btn" data-action="scroll-to" data-target="rs-sell">Sell a ticket</button><button class="btn secondary" data-action="scroll-to" data-target="rs-forsale">Browse tickets</button></div></div><div class="rs-example" aria-label="Example of the price cap"><span class="rs-ex-label">EXAMPLE · FACE VALUE Rp 450.000</span><div class="rs-ex-row bad"><span>Scalper site</span><b>Rp 1.350.000</b></div><div class="rs-ex-row good"><span>Ticketrue ceiling</span><b>Rp 450.000</b></div><p>Nobody gets priced out of a night they were meant to see.</p></div></div></div><div class="container rs-rules"><div><b>01</b><strong>Capped price</strong><p>You can’t list above what you paid. The contract refuses anything higher.</p></div><div><b>02</b><strong>Instant hand-over</strong><p>Payment and ownership switch hands together, in one step.</p></div><div><b>03</b><strong>5% to the show</strong><p>A small share of every resale goes back to the organizer.</p></div></div><div class="container rs-block" id="rs-forsale"><div class="rs-head"><h2>On sale now</h2>${n!==null?`<span class="rs-count">${n}</span>`:''}${demo&&listings.length<3?'<button class="text-button" data-action="demo-resale-reset">Restore sample listings</button>':''}</div><div id="resale-all" class="rs-grid">${demo?(listings.length?listings.map(demoCard).join(''):'<div class="rs-empty"><strong>Nothing is listed right now.</strong><p>List one of your tickets, or restore the sample listings.</p></div>'):'<p class="notice">Reading listings from BOT Chain…</p>'}</div></div><div class="container rs-block" id="rs-sell"><div class="rs-head"><h2>Sell your ticket</h2>${demo?'':`<button class="btn secondary" data-action="sync-tickets">${wallet?'Refresh from chain':'Connect wallet'}</button>`}</div><div id="resale-mine" class="rs-mine-list">${sell}</div></div></section>`}
async function loadResellPage(){if(demoMode())return;const all=$('#resale-all');if(!all)return;try{const list=await web3.listings();if(!$('#resale-all'))return;$('#resale-all').innerHTML=list.length?list.map(chainCard).join('')+'<div id="market-state" role="status"></div>':'<div class="rs-empty"><strong>Nothing is listed right now.</strong><p>When someone lists a ticket, it appears here.</p></div>'}catch(err){if($('#resale-all'))$('#resale-all').innerHTML='<p class="notice error">'+esc(err.message)+'</p>'}$$('#resale-mine [data-resale-for]').forEach(b=>loadResaleBox({id:b.dataset.resaleFor}))}
function gate(){return `<section class="container page gate"><span class="eyebrow">GATE CHECK-IN</span><h1>Is this ticket good to go?</h1><p class="muted">Enter a ticket ID to check it on BOT Chain. Gate staff can mark it as used, so it can’t be admitted twice.</p><form id="gate-form" class="row gate-form"><label class="sr-only" for="gate-id">Ticket ID</label><input id="gate-id" name="id" placeholder="Ticket ID or pasted link, e.g. 12" required><button class="btn">Check ticket</button></form><div id="gate-result" role="status" class="spacer"></div></section>`}
async function gateLookup(id){id=String(id).match(/verify\/(\d+)/)?.[1]||String(id).trim();const out=$('#gate-result');if(!out)return;if(!contractAddress){out.innerHTML='<p class="notice">The BOT Chain contract is not configured yet.</p>';return}out.innerHTML='<p class="notice">Checking BOT Chain…</p>';try{const t=await web3.ticketInfo(id);if(!t.exists){out.innerHTML='<div class="gate-card bad"><strong>NO SUCH TICKET</strong><p>Nothing was issued with ID '+esc(id)+'.</p></div>';return}const e=eventBy(t.eventId);out.innerHTML=`<div class="gate-card ${t.used?'bad':'ok'}"><strong>${t.used?'ALREADY USED':'VALID · NOT YET USED'}</strong><h2>${esc(e?.title||'Event '+t.eventId)}</h2><p>${esc(t.seat?'Seat '+t.seat:(e?.tiers[t.tierIndex]||'Ticket'))} · Ticket #${esc(t.id)} · holder ${esc(short(t.owner))}</p><button class="btn" data-action="gate-checkin" data-ticket="${esc(t.id)}" ${t.used?'disabled':''}>Mark as used</button><div id="gate-state" role="status"></div></div>`}catch(err){out.innerHTML='<p class="notice error">'+esc(err.message)+'</p>'}}
const h1Text=()=>{const h=$('#main h1');if(!h)return'';const c=h.cloneNode(true);c.querySelectorAll('br').forEach(b=>b.replaceWith(' '));return c.textContent.replace(/\s+/g,' ').trim()};
let cselN=0;
function enhanceSelects(root){if(!root)return;$$('select:not([data-csel])',root).forEach(sel=>{sel.dataset.csel='1';const id='csel-'+(++cselN),wrap=document.createElement('div'),btn=document.createElement('button'),list=document.createElement('ul');let active=-1;wrap.className='csel';btn.type='button';btn.className='csel-btn';btn.setAttribute('role','combobox');btn.setAttribute('aria-haspopup','listbox');btn.setAttribute('aria-expanded','false');btn.setAttribute('aria-controls',id);const lab=sel.getAttribute('aria-label');if(lab)btn.setAttribute('aria-label',lab);list.id=id;list.className='csel-list';list.setAttribute('role','listbox');list.hidden=true;sel.before(wrap);wrap.append(btn,list,sel);sel.classList.add('csel-native');sel.tabIndex=-1;sel.setAttribute('aria-hidden','true');
const sync=()=>{btn.innerHTML=`<span>${esc(sel.options[sel.selectedIndex]?.textContent||'')}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>`},paint=(scroll=true)=>[...list.children].forEach((li,i)=>{li.classList.toggle('active',i===active);if(i===active){btn.setAttribute('aria-activedescendant',li.id);if(scroll)li.scrollIntoView({block:'nearest'})}});
const open=()=>{list.innerHTML=[...sel.options].map((o,i)=>`<li role="option" id="${id}-${i}" data-i="${i}" aria-selected="${o.selected}" class="${o.selected?'selected':''}">${esc(o.textContent)}</li>`).join('');active=sel.selectedIndex;list.hidden=false;wrap.classList.add('open');btn.setAttribute('aria-expanded','true');paint()},close=()=>{list.hidden=true;wrap.classList.remove('open');btn.setAttribute('aria-expanded','false');btn.removeAttribute('aria-activedescendant')},pick=i=>{if(i<0||i>=sel.options.length)return;sel.selectedIndex=i;sync();close();sel.dispatchEvent(new Event('change',{bubbles:true}))};
btn.addEventListener('click',()=>list.hidden?open():close());
list.addEventListener('mousedown',e=>e.preventDefault());
list.addEventListener('click',e=>{const li=e.target.closest('li');if(li)pick(+li.dataset.i)});
list.addEventListener('mousemove',e=>{const li=e.target.closest('li');if(li&&+li.dataset.i!==active){active=+li.dataset.i;paint(false)}});
btn.addEventListener('keydown',e=>{const n=sel.options.length;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)open();else{active=Math.min(n-1,Math.max(0,active+(e.key==='ArrowDown'?1:-1)));paint()}}else if((e.key==='Home'||e.key==='End')&&!list.hidden){e.preventDefault();active=e.key==='Home'?0:n-1;paint()}else if((e.key==='Enter'||e.key===' ')&&!list.hidden){e.preventDefault();pick(active)}else if(e.key==='Escape'&&!list.hidden){e.stopPropagation();close()}else if(e.key==='Tab')close()});
btn.addEventListener('blur',()=>setTimeout(()=>{if(!wrap.contains(document.activeElement))close()},0));
sync()})}
// ---- Ticket pass (QR), calendar, share, image download ----
const baseUrl=()=>location.href.split('#')[0];
const verifyUrl=(id,extra='')=>`${baseUrl()}#/verify/${encodeURIComponent(id)}${extra}`;
const hashQuery=()=>new URLSearchParams(location.hash.split('?')[1]||'');
const anyTicket=id=>tickets.find(t=>String(t.id)===String(id));
let passTimer=null;
function startPassTimer(exp,t){clearInterval(passTimer);const tick=()=>{const left=exp-Math.floor(Date.now()/1000),el=$('#pass-left');if(!el){clearInterval(passTimer);return}if(left<=0){clearInterval(passTimer);renderPass(t);toast('Live pass expired. Sign a new one when you need it.');return}el.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0')};tick();passTimer=setInterval(tick,1000)}
async function renderPass(t,signed=null){const box=$('#pass-box');if(!box)return;try{const live=!!signed&&!t.demo,url=live?verifyUrl(t.id,`?e=${signed.exp}&s=${signed.sig}`):verifyUrl(t.id),m=await qrMatrix(url);if(!$('#pass-box'))return;$('#pass-box').innerHTML=`<div class="pass"><div class="pass-qr">${qrSvg(m,{label:'Ticket QR code'})}</div><div class="pass-info"><span class="eyebrow">${live?'LIVE PASS · SIGNED BY YOUR WALLET':t.demo?'DEMO PASS':'TICKET LINK'}</span><h3>${live?'Show this at the gate.':'Scan to check this ticket.'}</h3><p>${live?'Valid for <b id="pass-left">5:00</b>. It proves you hold the wallet, so a screenshot stops working.':t.demo?'Demo tickets open a demo page and are not valid for admission.':'Anyone can scan this to check the ticket on BOT Chain. Sign a live pass to prove you hold it.'}</p><div class="actions">${t.demo?'':`<button class="btn" data-action="pass-sign" data-ticket="${esc(t.id)}">${live?'Refresh live pass':'Show live pass'}</button>`}<button class="text-button" data-action="copy-link" data-link="${esc(url)}">Copy link</button></div><div id="pass-state" role="status"></div></div></div>`;if(live)startPassTimer(signed.exp,t)}catch{if($('#pass-box'))$('#pass-box').innerHTML='<p class="notice">The QR code could not be generated.</p>'}}
const icsText=(t,e)=>{const start=new Date(`${e.date}T${e.time}:00+07:00`),end=new Date(start.getTime()+3*3600e3),f=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),q=s=>String(s).replace(/([,;\\])/g,'\\$1').replace(/\n/g,'\\n');return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Ticketrue//Concert tickets//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT',`UID:${t.id}@ticketrue`,`DTSTAMP:${f(new Date())}`,`DTSTART:${f(start)}`,`DTEND:${f(end)}`,`SUMMARY:${q(e.title+' · '+e.artist)}`,`LOCATION:${q(e.venue+', '+e.city)}`,`DESCRIPTION:${q((t.seat?'Seat '+t.seat:t.tier)+' · Ticket '+t.id+(t.demo?' (demo ticket)':''))}`,'BEGIN:VALARM','TRIGGER:-PT3H','ACTION:DISPLAY','DESCRIPTION:Your concert starts in 3 hours','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n')};
function saveBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000)}
function addToCalendar(t){const e=eventBy(t.eventId);if(!e)throw Error('Concert not found.');saveBlob(new Blob([icsText(t,e)],{type:'text/calendar;charset=utf-8'}),'ticketrue-'+e.slug+'.ics');toast('Calendar file downloaded.')}
async function shareTicket(t){const e=eventBy(t.eventId);if(!e)throw Error('Concert not found.');const url=baseUrl()+'#/event/'+e.slug,text=`I’m going to ${e.title} on ${date(e.date)}. Get your ticket on Ticketrue.`;if(navigator.share){try{await navigator.share({title:e.title,text,url})}catch(err){if(err.name!=='AbortError')throw err}return}await navigator.clipboard.writeText(text+' '+url);toast('Link copied. Paste it anywhere.')}
function wrapLines(g,text,max,limit){const words=String(text).split(' '),lines=[];let cur='';for(const w of words){const next=cur?cur+' '+w:w;if(g.measureText(next).width>max&&cur){lines.push(cur);cur=w}else cur=next}if(cur)lines.push(cur);return lines.slice(0,limit)}
async function downloadTicketImage(t){const e=eventBy(t.eventId);if(!e)throw Error('Concert not found.');const m=await qrMatrix(verifyUrl(t.id)),W=1200,H=520,c=document.createElement('canvas');c.width=W;c.height=H;const g=c.getContext('2d');if(!g)throw Error('Your browser cannot draw the ticket image.');const navy='#0c2d50',orange='#F9A12B',ui='system-ui,-apple-system,"Segoe UI",Roboto,sans-serif',mono='ui-monospace,Menlo,Consolas,monospace';
g.fillStyle='#ffffff';g.fillRect(0,0,W,H);
g.fillStyle=navy;g.fillRect(20,20,840,480);g.fillStyle=orange;g.fillRect(860,20,320,480);
g.fillStyle='#ffffff';for(const y of [20,500]){g.beginPath();g.arc(860,y,24,0,Math.PI*2);g.fill()}
g.strokeStyle=navy;g.lineWidth=3;g.setLineDash([10,10]);g.beginPath();g.moveTo(860,56);g.lineTo(860,464);g.stroke();g.setLineDash([]);
g.textBaseline='alphabetic';g.fillStyle='#ffffff';g.font=`700 36px ${ui}`;g.fillText('ticketrue',70,92);const bw=g.measureText('ticketrue').width;g.fillStyle=orange;g.fillText('.',70+bw,92);
g.fillStyle=orange;g.font=`700 20px ${mono}`;g.fillText(('ADMIT ONE · '+e.artist).toUpperCase().slice(0,52),70,150);
g.fillStyle='#ffffff';g.font=`700 62px ${ui}`;const lines=wrapLines(g,e.title,740,2);lines.forEach((l,i)=>g.fillText(l,70,232+i*68));
const y0=232+lines.length*68;g.fillStyle='#9dbbdc';g.font=`500 26px ${ui}`;g.fillText(`${date(e.date)} · ${e.time} WIB · ${e.venue}, ${e.city}`.slice(0,64),70,y0+8);
g.fillStyle='#ffffff';g.font=`700 30px ${ui}`;g.fillText(t.seat?`${t.tier||''} · Seat ${t.seat}`.replace(/^ · /,''):(t.tier||'General'),70,y0+58);
g.fillStyle='#9dbbdc';g.font=`500 22px ${mono}`;g.fillText('TICKET '+t.id,70,y0+100);
if(t.demo){g.fillStyle=orange;g.font=`700 20px ${mono}`;g.fillText('DEMO TICKET · NOT AN ADMISSION PASS',70,478)}
const qs=240,qx=900,qy=64,cell=qs/(m.n+4);g.fillStyle='#ffffff';g.fillRect(qx,qy,qs,qs);g.fillStyle=navy;for(let r=0;r<m.n;r++)for(let k=0;k<m.n;k++)if(m.dark(r,k))g.fillRect(qx+(k+2)*cell,qy+(r+2)*cell,Math.ceil(cell),Math.ceil(cell));
g.fillStyle=navy;g.textAlign='center';g.font=`700 18px ${mono}`;g.fillText('SCAN TO CHECK',qx+qs/2,qy+qs+40);g.font=`500 16px ${mono}`;g.fillText(String(t.id).slice(0,22),qx+qs/2,qy+qs+66);g.textAlign='left';
await new Promise((res,rej)=>c.toBlob(b=>b?(saveBlob(b,'ticketrue-'+e.slug+'-'+String(t.id).slice(-6)+'.png'),res()):rej(Error('Could not create the image.')),'image/png'));toast('Ticket image saved.')}

// ---- Public ticket check page ----
function verifyPage(){return `<section class="container page verify-page"><span class="eyebrow">TICKET CHECK</span><h1>Is this ticket real?</h1><p class="muted">This page reads the Ticketrue contract on BOT Chain. No login or wallet needed.</p><div id="verify-card" class="spacer"><p class="notice">Checking BOT Chain…</p></div></section>`}
const vCard=(tone,label,title,lines,extra='')=>`<div class="gate-card ${tone}"><strong>${esc(label)}</strong><h2>${esc(title)}</h2>${lines.map(l=>`<p>${l}</p>`).join('')}${extra}</div>`;
async function loadVerify(id){const box=$('#verify-card');if(!box)return;try{
 if(/^DEMO-/i.test(id)){box.innerHTML=vCard('warn','DEMO TICKET','Not a blockchain ticket',['This is a demo ticket kept in one browser. It is not recorded on BOT Chain and is not valid for admission.']);return}
 if(!contractAddress){box.innerHTML=vCard('warn','NOT CONFIGURED','The contract is not live yet',['This site has no BOT Chain contract configured, so tickets cannot be checked on-chain yet.']);return}
 if(!/^\d+$/.test(id)){box.innerHTML=vCard('bad','NO SUCH TICKET','Unrecognised ticket',['That is not a Ticketrue ticket ID.']);return}
 const t=await web3.ticketInfo(id);if(!$('#verify-card'))return;
 if(!t.exists){box.innerHTML=vCard('bad','NO SUCH TICKET','Nothing was issued with this ID',[`Ticket #${esc(id)} does not exist on this contract.`]);return}
 const q=hashQuery(),exp=q.get('e'),sig=q.get('s');let holder;
 if(sig&&exp){if(Number(exp)<Date.now()/1000)holder={tone:'warn',text:'This live pass has expired. Ask the holder to refresh it.'};else{try{const who=await web3.recoverSigner(web3.passMessage(id,exp),sig);holder=who.toLowerCase()===t.owner.toLowerCase()?{tone:'ok',text:'<b>Holder confirmed.</b> This pass was signed moments ago by the wallet that owns the ticket.'}:{tone:'bad',text:'<b>Signature does not match the ticket owner.</b> Do not admit.'}}catch{holder={tone:'bad',text:'The pass signature could not be checked. Do not admit.'}}}}
 else holder={tone:'warn',text:'No live pass attached. Ownership is on-chain, but the holder is not proven. Ask them to show a live pass.'};
 const e=eventBy(t.eventId),tone=t.used?'bad':holder.tone==='bad'?'bad':'ok',label=t.used?'ALREADY USED':holder.tone==='bad'?'DO NOT ADMIT':'VALID TICKET';
 box.innerHTML=vCard(tone,label,e?.title||'Event '+t.eventId,[`${esc(t.seat?'Seat '+t.seat:(e?.tiers?.[t.tierIndex]||'Ticket'))} · Ticket #${esc(t.id)} · holder ${esc(short(t.owner))}`,holder.text,`<a href="${chainConfig.blockExplorerUrls[0]}/address/${contractAddress}" target="_blank" rel="noreferrer">View contract on the explorer ↗</a>`],`<div class="actions spacer"><button class="btn" data-action="gate-checkin" data-ticket="${esc(t.id)}" ${t.used?'disabled':''}>Mark as used (gate staff)</button></div><div id="gate-state" role="status"></div>`)}
 catch(err){if($('#verify-card'))$('#verify-card').innerHTML='<p class="notice error">'+esc(err.message)+'</p>'}}

// ---- Organizer dashboard ----
function dashboard(){return `<section class="dash-page"><div class="rs-band dash-band"><div class="container"><span class="eyebrow">ORGANIZER DASHBOARD</span><h1>Your nights,<br><em>by the numbers.</em></h1><p>Sales, resale, gate check-ins and payouts, read straight from the Ticketrue contract on BOT Chain.</p><div id="dash-role" class="dash-role"></div></div></div><div class="container dash-body"><div id="dash-kpis" class="dash-kpis"></div><div id="dash-sales" class="dash-block"></div><div id="dash-publish" class="dash-block"></div><div id="dash-staff" class="dash-block"></div><div id="dash-pay" class="dash-block"></div><div id="dash-state" role="status"></div></div></section>`}
const dKpi=(n,label,extra='')=>`<div class="dash-kpi"><strong>${n}</strong><span>${label}</span>${extra}</div>`;
async function loadDashboard(){if(!$('#dash-kpis'))return;
 if(demoMode()){const sold=tickets.filter(t=>t.demo),rev=sold.reduce((s,t)=>s+(Number(t.price)||0),0),by=events.filter(e=>!e.draft).map(e=>({e,n:sold.filter(t=>t.eventId===e.id).length})),max=Math.max(1,...by.map(x=>x.n));
  $('#dash-role').innerHTML='<i></i>DEMO VIEW · numbers come from tickets created in this browser. It switches to live contract data once the contract is deployed.';
  $('#dash-kpis').innerHTML=dKpi(sold.length,'Tickets issued')+dKpi(money(rev),'Demo sales')+dKpi(listings.length,'Resale listings')+dKpi('—','Checked in');
  $('#dash-sales').innerHTML='<div class="rs-head"><h2>Sales by concert</h2></div>'+by.map(({e,n})=>`<div class="dash-row"><span><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${esc(e.city)}</small></span><div class="dash-bar"><i style="width:${Math.round(n/max*100)}%"></i></div><b>${n} sold</b></div>`).join('');
  $('#dash-publish').innerHTML='<div class="rs-empty"><strong>On-chain publishing, gate staff and payouts</strong><p>These tools unlock after the Ticketrue contract is deployed and its address is set in config.js.</p></div>';return}
 $('#dash-kpis').innerHTML='<p class="notice">Reading BOT Chain…</p>';
 try{const list=events.filter(e=>!e.draft),d=await web3.dashboard(list);if(!$('#dash-kpis'))return;const me=!!wallet&&wallet.toLowerCase()===d.organizer.toLowerCase();
  $('#dash-role').innerHTML=me?'<i class="on"></i>YOU ARE THE ORGANIZER':`<i></i>READ-ONLY · organizer wallet is ${esc(short(d.organizer))} ${wallet?'':'<button class="text-button" data-action="wallet">Connect wallet</button>'}`;
  $('#dash-kpis').innerHTML=dKpi(d.issued,'Tickets issued')+dKpi(bot(d.balance),'Withdrawable balance')+dKpi(d.resales.count,'Resales',`<small>${bot(d.resales.volume)} traded</small>`)+dKpi(d.checkins,'Checked in');
  $('#dash-sales').innerHTML='<div class="rs-head"><h2>Sales by concert</h2></div>'+d.perEvent.map(p=>{const e=eventBy(p.id);if(!e)return'';if(!p.live)return `<div class="dash-row"><span><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${esc(e.city)}</small></span><span class="dash-off">Not on-chain yet</span></div>`;return `<div class="dash-event"><div class="dash-ehead"><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${esc(e.city)}${p.demo?' · free demo claims on':''}</small></div>${p.options.map((o,i)=>o?`<div class="dash-row"><span><small>${esc(tierName(e,i)||'Tier '+(i+1))} · ${bot(o.price)}</small></span><div class="dash-bar"><i style="width:${o.capacity?Math.round(Number(o.issued)/Number(o.capacity)*100):0}%"></i></div><b>${o.issued}/${o.capacity}</b></div>`:'').join('')}</div>`}).join('');
  const off=d.perEvent.filter(p=>!p.live);
  $('#dash-publish').innerHTML=!off.length?'':`<div class="rs-head"><h2>Publish on-chain</h2></div>`+(me?off.map(p=>{const e=eventBy(p.id),seat=e.mode==='seat',n=seat?3:e.tiers.length,nm=i=>seat?seatZones[i].name:e.tiers[i],rp=i=>e.price+(seat?seatZones[i].add:i*250000),def=r=>String(Number((r/45e6).toFixed(4)));return `<form class="dash-form" data-dash="publish" data-event="${esc(e.id)}" data-mode="${seat?'seat':'tier'}"><div class="dash-fhead"><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${seat?'three seat-zone prices':n+' tiers'}</small></div><div class="dash-fields">${Array.from({length:n},(_,i)=>`<label>${esc(nm(i))} · price (BOT)<input name="price${i}" inputmode="decimal" value="${def(rp(i))}"></label><label>${esc(nm(i))} · ${seat?'seats (max 20)':'tickets'}<input name="cap${i}" inputmode="numeric" value="${seat?20:Math.max(20,80-i*20)}"></label>`).join('')}</div>${isMainnet?'':'<label class="dash-check"><input type="checkbox" name="demo" checked> Allow free demo claims (testnet only)</label>'}<button class="btn">Create on-chain</button></form>`}).join(''):'<p class="notice">Connect the organizer wallet to create the remaining concerts on-chain.</p>');
  $('#dash-staff').innerHTML=`<div class="rs-head"><h2>Gate staff</h2></div>${d.staff.length?d.staff.map(a=>`<div class="dash-row"><span><strong>${esc(short(a))}</strong><small>${esc(a)}</small></span>${me?`<button class="text-button" data-action="dash-staff-remove" data-addr="${esc(a)}">Remove</button>`:''}</div>`).join(''):'<p class="notice">No staff added yet. The organizer wallet can always check tickets in.</p>'}${me?'<form class="dash-inline" data-dash="staff"><input name="addr" placeholder="Staff wallet address 0x…" aria-label="Staff wallet address"><button class="btn secondary">Add staff</button></form>':''}`;
  $('#dash-pay').innerHTML=`<div class="rs-head"><h2>Payouts</h2></div><p class="muted">${bot(d.balance)} is ready to withdraw. Primary sales and the 5% resale share collect in the contract.</p>${me?`<form class="dash-inline" data-dash="withdraw"><input name="addr" value="${esc(wallet)}" aria-label="Recipient wallet"><button class="btn">Withdraw</button></form>`:'<p class="notice">Only the organizer wallet can withdraw.</p>'}`}
 catch(err){if($('#dash-kpis'))$('#dash-kpis').innerHTML='<p class="notice error">'+esc(err.message)+'</p>'}}
async function doDash(f,d){const kind=f.dataset.dash,st=txStatus('#dash-state');try{
 if(kind==='publish'){const e=eventBy(f.dataset.event),seat=f.dataset.mode==='seat',n=seat?3:e.tiers.length,prices=[],caps=[];for(let i=0;i<n;i++){prices.push(toWei(d.get('price'+i)));const c=Number(d.get('cap'+i));if(!Number.isInteger(c)||c<1||(seat&&c>20))throw Error(seat?'Seats per zone must be a whole number from 1 to 20.':'Tickets per tier must be a whole number of at least 1.');caps.push(c)}const startsAt=Math.floor(new Date(`${e.date}T${e.time}:00+07:00`).getTime()/1000);if(startsAt<=Date.now()/1000)throw Error('This concert date has already passed.');await web3.createEventTx(e.id,{seated:seat,demo:d.has('demo'),startsAt,prices,caps},st);toast(e.title+' is live on-chain.')}
 else{const a=String(d.get('addr')||'').trim();if(!/^0x[0-9a-fA-F]{40}$/.test(a))throw Error('Enter a valid wallet address.');if(kind==='staff'){await web3.setStaffTx(a,true,st);toast('Gate staff added.')}else{await web3.withdrawTx(a,st);toast('Withdrawal sent.')}}
 await loadDashboard()}catch(err){toast(err.message||'Something went wrong.');if($('#dash-state'))$('#dash-state').innerHTML='<p class="notice error spacer">'+esc(err.message||'')+'</p>'}}
// ---- Availability badges, waitlist, saved concerts ----
let saved=read('saved',[]),waitlist=read('waitlist',[]);const stockCache={},resaleCount={};
function stockState(e){let left,cap;if(contractAddress){const s=stockCache[e.id];if(!s)return{state:'unknown'};if(!s.live)return{state:'soon'};left=s.left;cap=s.cap}else{cap=e.mode==='seat'?53:189;left=e.id in demoStock?demoStock[e.id]:Math.max(0,cap-tickets.filter(t=>t.eventId===e.id).length)}return{state:left<=0?'sold':left<=Math.max(10,Math.round(cap*.1))?'low':'ok',left,cap}}
const stockBadge=e=>{const s=stockState(e);return s.state==='sold'?'<span class="stock stock-sold">Sold out</span>':s.state==='soon'?'<span class="stock stock-soon">On sale soon</span>':s.state==='low'?`<span class="stock stock-low">Only ${s.left} left</span>`:''};
const isOff=e=>{const s=stockState(e).state;return s==='sold'||s==='soon'};
const heartBtn=e=>{const on=saved.includes(e.id);return `<span class="heart${on?' on':''}" role="button" tabindex="0" data-action="save" data-event="${e.id}" aria-pressed="${on}" aria-label="Save ${esc(e.title)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.5s-7.5-4.6-7.5-10A4.3 4.3 0 0 1 12 7.8a4.3 4.3 0 0 1 7.5 2.7c0 5.4-7.5 10-7.5 10Z"/></svg></span>`};
function waitlistBox(e){const s=stockState(e).state;if(s!=='sold'&&s!=='soon')return `<div id="waitlist-box" data-event="${e.id}" hidden></div>`;const on=waitlist.includes(e.id),n=demoMode()?listings.filter(l=>l.eventId===e.id):(resaleCount[e.id]||[]),rl=n.length?`<p class="waitlist-resale"><b>${n.length} resale ticket${n.length>1?'s':''}</b> from ${demoMode()?money(Math.min(...n.map(l=>l.price))):bot(n.reduce((m,l)=>l.listed<m?l.listed:m,n[0].listed))}. <a href="#/resell">See resale ↗</a></p>`:'';return `<div id="waitlist-box" class="waitlist" data-event="${e.id}"><span class="eyebrow">${s==='sold'?'SOLD OUT':'NOT ON SALE YET'}</span><h3>${s==='sold'?'Missed it? Get in line.':'Be first in line.'}</h3><p>${s==='sold'?'Tickets come back when someone resells or the organizer adds more.':'Tickets open once the organizer publishes this concert.'}</p>${rl}<button class="btn ${on?'secondary':''}" data-action="wl-toggle" data-event="${e.id}">${on?'✓ On the waitlist · Leave':'Join the waitlist'}</button><small>Saved on this device only.</small></div>`}
function paintStocks(){$$('[data-stock]').forEach(el=>{const e=eventBy(el.dataset.stock);if(e)el.innerHTML=stockBadge(e)});const box=$('#waitlist-box');if(box){const e=eventBy(box.dataset.event);if(e)box.outerHTML=waitlistBox(e)}const sel=$('.selector'),id=path().startsWith('/event/')?eventBy(path().split('/')[2])?.id:null;if(sel&&id){const e=eventBy(id);sel.toggleAttribute('inert',isOff(e));sel.classList.toggle('is-off',isOff(e))}}
async function loadStocks(){const list=events.filter(e=>!e.draft);if(!contractAddress){paintStocks();return}await Promise.all(list.map(async e=>{try{const s=await web3.stockOf(e);stockCache[e.id]=s;if(!s.live||s.left<=0){try{resaleCount[e.id]=await web3.listings(e.id)}catch{}}}catch{}}));paintStocks();const back=list.filter(e=>waitlist.includes(e.id)&&!isOff(e)&&stockState(e).state!=='unknown');if(back.length){waitlist=waitlist.filter(id=>!back.some(e=>e.id===id));save('waitlist',waitlist);toast('Tickets are back: '+back.map(e=>e.title).join(', '))}}
function toggleSaved(id){const on=saved.includes(id);saved=on?saved.filter(x=>x!==id):[...saved,id];save('saved',saved);$$(`[data-action=save][data-event="${id}"]`).forEach(b=>{b.classList.toggle('on',!on);b.setAttribute('aria-pressed',String(!on));const l=b.querySelector('.save-label');if(l)l.textContent=!on?'Saved':'Save'});toast(!on?'Saved to your list.':'Removed from your list.');if($('#save-lists'))$('#save-lists').outerHTML=saveLists()}
function toggleWaitlist(id){const on=waitlist.includes(id);waitlist=on?waitlist.filter(x=>x!==id):[...waitlist,id];save('waitlist',waitlist);toast(on?'Left the waitlist.':'You’re on the waitlist. We’ll flag it here when tickets return.');paintStocks();if($('#save-lists'))$('#save-lists').outerHTML=saveLists()}
function saveLists(){const row=(id,kind)=>{const e=eventBy(id);return e?`<div class="save-row"><a href="#/event/${esc(e.slug)}"><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${esc(e.city)}${kind==='wl'?' · '+(stockState(e).state==='sold'?'sold out':stockState(e).state==='soon'?'not on sale yet':'available'):''}</small></a><button class="text-button" data-action="${kind==='wl'?'wl-toggle':'save'}" data-event="${e.id}">Remove</button></div>`:''};const s=saved.map(id=>row(id,'s')).join(''),w=waitlist.map(id=>row(id,'wl')).join('');if(!s&&!w)return '<div id="save-lists"></div>';return `<div id="save-lists" class="save-lists">${s?`<div class="save-col"><h2>Saved concerts</h2>${s}</div>`:''}${w?`<div class="save-col"><h2>Waitlist</h2>${w}</div>`:''}</div>`}
// ---- Event guide: schedule, venue, FAQ, similar concerts ----
function guideInfo(e){const i=e.info||seed.find(s=>s.id===e.id)?.info;if(i)return i;const [h,m]=String(e.time||'19:00').split(':').map(Number),d=new Date(2000,0,1,h,m-60);return{schedule:[[String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'),'Doors open'],[e.time,e.artist+' · '+e.title]],venue:'',age:'All ages.',bag:'Small bags only.'}}
function eventGuide(e){const i=guideInfo(e),faq=[['What time should I arrive?',`Doors open at ${i.schedule[0][0]} WIB and the show starts at ${e.time} WIB. Arriving 30 to 45 minutes after doors open avoids the queue.`],['Who can attend?',i.age],['What can I bring?',i.bag],['Can I resell my ticket?','Yes. On the <a href="#/resell">Resell page</a>, at or below what you paid. The organizer keeps 5% of each resale.',true],['How many tickets can I buy?','One ticket per wallet for each concert.'],['Is this a real concert?','No. Ticketrue is a prototype. The concerts, artists and venues here are fictional, and demo payments move no real money.']],rel=events.filter(x=>!x.draft&&x.id!==e.id).map(x=>({x,s:(x.city===e.city?2:0)+(x.mode===e.mode?1:0)})).sort((p,q)=>q.s-p.s).slice(0,3).map(p=>p.x);return `<div class="guide"><section class="guide-block"><span class="eyebrow">THE NIGHT, HOUR BY HOUR</span><h2>Schedule</h2><ol class="timeline">${i.schedule.map(([t,l])=>`<li><time>${esc(t)}<small>WIB</small></time><span>${esc(l)}</span></li>`).join('')}</ol></section><section class="guide-block"><span class="eyebrow">THE VENUE</span><h2>${esc(e.venue)}</h2><p class="muted">${esc(i.venue||e.city)}</p><dl class="guide-facts"><div><dt>City</dt><dd>${esc(e.city)}</dd></div><div><dt>Doors</dt><dd>${esc(i.schedule[0][0])} WIB</dd></div><div><dt>Showtime</dt><dd>${esc(e.time)} WIB</dd></div><div><dt>Age</dt><dd>${esc(i.age)}</dd></div></dl></section><section class="guide-block guide-faq"><span class="eyebrow">GOOD TO KNOW</span><h2>Questions, answered.</h2>${faq.map(([q,ans,html])=>`<details class="faq"><summary>${esc(q)}</summary><p>${html?ans:esc(ans)}</p></details>`).join('')}</section></div>${rel.length?`<section class="guide-block guide-more"><span class="eyebrow">KEEP THE NIGHTS COMING</span><h2>You might also like</h2><div class="grid">${rel.map(card).join('')}</div></section>`:''}`}
function render(){clearInterval(timer);clearInterval(passTimer);clearInterval(liveTimer);clearInterval(aboutTimer);carousel?.dispose();carousel=null;heroTicket?.dispose();heroTicket=null;loginSceneVersion++;loginScene?.dispose();loginScene=null;machine?.dispose();machine=null;if(tour)endTour();shell();let p=path(),html='';if(['/profile','/organizer'].some(x=>p===x||p.startsWith(x+'/'))&&!user){returnTo=p;go('/login');return}if(p==='/')html=home();else if(p==='/discover')html=discover();else if(p==='/login'||p==='/signup')html=login(p==='/signup');else if(p==='/forgot')html='<section class="container page prose"><h1>Need a fresh start?</h1><p>Demo sign-in does not store passwords, so there is nothing to reset. Use sample details or the demo button to continue.</p><a class="btn" href="#/login">Back to login →</a></section>';else if(p.startsWith('/event/'))html=detail(eventBy(p.split('/')[2]));else if(p==='/checkout')html=checkout();else if(p==='/tickets')html=ticketsPage();else if(p.startsWith('/tickets/'))html=ticketPage(p.split('/')[2]);else if(p.startsWith('/reveal/'))html=reveal(p.split('/')[2]);else if(p==='/machine')html=reveal(null,true);else if(p==='/profile')html=profile();else if(p==='/organizer')html=organizer();else if(p==='/resell')html=resell();else if(p.startsWith('/verify/'))html=verifyPage();else if(p==='/dashboard')html=dashboard();else if(p==='/gate')html=gate();else if(p==='/about')html=about();else if(p==='/privacy'||p==='/terms')html=legal(p.slice(1));else html=missing();$('#main').innerHTML=html;enhanceSelects($('#main'));initMotion(p);document.title=(p==='/'?'Ticketrue — Concert Tickets, Verified On-Chain':(h1Text()||'Ticketrue')+' — Ticketrue');if(p==='/discover')carousel=mountCarousel($('#featured-carousel'));if(p==='/')heroTicket=mountHeroTicket($('#hero-home'));if(p==='/discover'&&(searchQuery||searchCity||searchMode))filterEvents();if(p==='/login'||p==='/signup')loadLoginScene();if(p==='/checkout'){startCountdown();contextTour('checkout');if(payType==='bot')loadQuote()}if(p==='/'){loadLive();liveTimer=setInterval(loadLive,20000)}if(p.startsWith('/event/')){loadAvailability(eventBy(p.split('/')[2]));loadMarket(eventBy(p.split('/')[2]))}if(p==='/'||p==='/discover'||p.startsWith('/event/')||p==='/tickets')loadStocks();if(p==='/resell')loadResellPage();if(p.startsWith('/verify/'))loadVerify(decodeURIComponent(p.split('/')[2]));if(p==='/dashboard')loadDashboard();if(p==='/about'){tickAbout();aboutTimer=setInterval(tickAbout,1000)}if(p.startsWith('/tickets/')){const tk=ownTickets().find(x=>String(x.id)===p.split('/')[2]);if(tk){renderPass(tk);if(!tk.demo)loadResaleBox(tk)}}if(p.startsWith('/event/'))contextTour(!read('tour:event',false)?'event':eventBy(p.split('/')[2])?.mode==='seat'?'seat':'tier');if(p==='/tickets')contextTour('tickets');if(p.startsWith('/reveal/')||p==='/machine')loadMachine()}
document.addEventListener('input',e=>{if(e.target.id==='search'){searchQuery=e.target.value;filterEvents()}});document.addEventListener('change',e=>{if(e.target.id.endsWith('-filter'))filterEvents()});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='hero-search'){searchQuery=String(d.get('q')||'').trim();searchCity=String(d.get('city')||'');searchMode=String(d.get('mode')||'');go('/discover');return}if(f.id==='gate-form'){gateLookup(String(d.get('id')||'').trim());return}if(f.hasAttribute('data-dash')){doDash(f,d);return}if(f.hasAttribute('data-demo-resale')){try{demoList(f.dataset.ticket,d.get('price'))}catch(err){toast(err.message)}return}if(f.hasAttribute('data-resale-form')){doResale(f.dataset.ticket,d.get('price'));return}if(f.id==='header-search-form'){searchQuery=String(d.get('q')||'').trim();if(path()==='/discover'){const input=$('#search');if(input){input.value=searchQuery;filterEvents()}}else go('/discover');return}if(f.id==='login-form'){loginSuccess(String(d.get('name')||d.get('email').split('@')[0]),String(d.get('email')),d.has('remember'))}if(f.id==='event-form'){const id=f.dataset.id;const old=id?eventBy(id):null;const name=String(d.get('title')).trim(),tiers=String(d.get('tiers')).split(',').map(x=>x.trim()).filter(Boolean);if(!tiers.length){toast('Add at least one ticket tier.');return}const updated={...(old||{}),id:old?.id||Math.max(...events.map(x=>x.id))+1,slug:old?.slug||'concert-'+crypto.randomUUID().slice(0,8),title:name,artist:String(d.get('artist')),venue:String(d.get('venue')),city:String(d.get('city')),date:String(d.get('date')),mode:String(d.get('mode')),price:Number(d.get('price')),tiers,draft:d.has('draft'),genre:old?.genre||'Live Music',description:old?.description||'A new fictional live experience.',time:old?.time||'19:00',color:old?.color||'blue'};if(old)events=events.map(x=>x.id===old.id?updated:x);else events.push(updated);save('events',events);close();render();toast('Event saved on this device.')}});
document.addEventListener('click',async ev=>{const b=ev.target.closest('button,[data-action]');if(!b)return;try{if(b.hasAttribute('data-close')){close();return}if(b.dataset.aboutMode){const mode=b.dataset.aboutMode;$$('[data-about-mode]').forEach(x=>{const selected=x.dataset.aboutMode===mode;x.classList.toggle('active',selected);x.setAttribute('aria-pressed',selected)});$('#about-choice').innerHTML=aboutChoice(mode);return}if(b.dataset.seat){const e=eventBy(b.dataset.event),info=seatDetails(e,b.dataset.seat);selectTicket(e,{seat:b.dataset.seat,tier:info.zone,tierIndex:0,price:info.price});return}if(b.dataset.tier!==undefined){const e=eventBy(b.dataset.event),i=+b.dataset.tier;selectTicket(e,{tier:e.tiers[i],tierIndex:i,price:e.price+i*250000});return}if(b.dataset.payType){payType=b.dataset.payType;render();return}if(b.dataset.payment){payment=b.dataset.payment;paymentRender();return}if(b.dataset.editEvent){eventForm(b.dataset.editEvent);return}if(b.dataset.verify){const t=tickets.find(t=>t.id===b.dataset.verify);const vr=$('#verify-result');if(t.demo){vr.textContent='Local demo record found. This is not an on-chain verification.';return}vr.textContent='Checking BOT Chain…';const ok=await web3.verifyTicket(t);vr.innerHTML=ok?`Ownership confirmed by the Ticketrue contract on BOT Chain. <a href="${chainConfig.blockExplorerUrls[0]}/address/${contractAddress}" target="_blank" rel="noreferrer">View contract ↗</a>`:'Ownership could not be confirmed.';return}switch(b.dataset.action){case'carousel-next':carousel?.next();break;case'carousel-prev':carousel?.prev();break;case'carousel-pause':carousel?.togglePause();break;case'toggle-search':{const shell=$('.nav-shell');const open=shell.classList.toggle('search-open');b.setAttribute('aria-expanded',String(open));if(open){shell.querySelector('.nav-links')?.classList.remove('open');shell.querySelector('.header-search input')?.focus()}break;}case'toggle-login-animation':if(loginScene){const paused=loginScene.toggle();b.textContent=paused?'Play animation':'Pause animation';b.setAttribute('aria-pressed',String(paused))}break;case'menu':$('.nav-shell')?.classList.remove('search-open');$('.nav-links').classList.toggle('open');b.setAttribute('aria-expanded',$('.nav-links').classList.contains('open'));break;case'how':$('#how').scrollIntoView({behavior:'smooth'});break;case'reset-filters':searchQuery='';searchCity='';searchMode='';go('/discover');render();break;case'clear-city':searchCity='';filterEvents();break;case'checkout':go('/checkout');break;case'demo-login':loginSuccess('Music Lover','demo@ticketrue.local',true);break;case'start-tour':startTour('global');break;case'skip-global':save('tour:global',true);close();break;case'tour-skip':endTour();break;case'tour-back':tour.index=Math.max(0,tour.index-1);drawTour();break;case'tour-next':if(++tour.index>=tours[tour.key].length){const key=tour.key;endTour();if(key==='event')contextTour(eventBy(path().split('/')[2])?.mode==='seat'?'seat':'tier')}else drawTour();break;case'wallet':walletDialog();break;case'connect':b.disabled=true;try{await connectWallet();close()}catch(err){$('#wallet-error').textContent=err.message}finally{b.disabled=false}break;case'disconnect':wallet='';web3.disconnect();close();render();break;case'simulate':b.disabled=true;b.textContent='Confirming demo payment…';clearInterval(timer);await new Promise(r=>setTimeout(r,700));paid=true;if(path()==='/checkout')paymentRender();break;case'retry-payment':paymentRender();break;case'copy-va':await navigator.clipboard.writeText('DEMO-VA-0000-1234');toast('Demo reference copied.');break;case'issue-demo':await issueDemo();break;case'issue-real':await issueReal();break;case'issue-claim':await issueReal(true);break;case'demo-resale-buy':demoBuy(b.dataset.ticket);break;case'demo-resale-cancel':demoCancel(b.dataset.ticket);break;case'demo-sim-sale':demoSimSale(b.dataset.ticket);break;case'demo-resale-reset':listings=[...seedListings(),...listings.filter(l=>!l.tid.startsWith('DEMO-RS-'))];save('listings',listings);render();break;case'price-chip':{const f=b.closest('form');f.elements.price.value=b.dataset.value;updateReceive(f);break}case'scroll-to':document.getElementById(b.dataset.target)?.scrollIntoView({behavior:'smooth'});break;case'save':ev.preventDefault();ev.stopPropagation();toggleSaved(Number(b.dataset.event));break;case'wl-toggle':toggleWaitlist(Number(b.dataset.event));break;case'pass-sign':{const t=anyTicket(b.dataset.ticket);if(!t)throw Error('Ticket not found.');const s=await web3.signPass(t.id);await renderPass(t,s);break}case'copy-link':await navigator.clipboard.writeText(b.dataset.link);toast('Link copied.');break;case'cal-add':addToCalendar(anyTicket(b.dataset.ticket));break;case'share-ticket':await shareTicket(anyTicket(b.dataset.ticket));break;case'dl-ticket':await downloadTicketImage(anyTicket(b.dataset.ticket));break;case'dash-staff-remove':await web3.setStaffTx(b.dataset.addr,false,txStatus('#dash-state'));await loadDashboard();break;case'resale-cancel':await web3.cancelResale(b.dataset.ticket,txStatus('#resale-state-'+b.dataset.ticket));await loadResaleBox({id:b.dataset.ticket});break;case'resale-buy':{const id=b.dataset.ticket;await connectWallet();await web3.buyResale(id,BigInt(b.dataset.price),txStatus('#market-state'));await syncTickets();toast('The ticket is yours.');go('/tickets/'+id);break}case'gate-checkin':{const id=b.dataset.ticket,who=await connectWallet();if(!await web3.isGate(who))throw Error('This wallet is not gate staff. Connect the organizer or a staff wallet.');await web3.checkIn(id,txStatus('#gate-state'));toast('Ticket checked in.');if($('#verify-card'))await loadVerify(id);else await gateLookup(id);break}case'preview-machine':go('/machine');break;case'replay':go('/discover');setTimeout(()=>startTour('global'),150);break;case'reset-tours':Object.keys(tours).forEach(k=>save('tour:'+k,false));toast('All tutorials reset.');break;case'logout':user=null;wallet='';order=null;paid=false;returnTo='/discover';web3.disconnect();localStorage.removeItem('tr2:user');sessionStorage.removeItem('tr2:user');if(tour)endTour();close();if(path()==='/')render();else go('/');toast('You’re logged out.');break;case'new-event':eventForm();break;case'sync-tickets':b.disabled=true;await connectWallet();if(!contractAddress){toast('Contract is not configured. Local demo tickets are shown.');break}await syncTickets();render();break}}catch(err){toast(err.message||'Something went wrong. Try again.');if($('#transaction-state'))$('#transaction-state').innerHTML='<p class="notice error spacer">'+esc(err.message)+'</p>'}finally{if(b.isConnected)b.disabled=false}});
document.addEventListener('click',e=>{const menu=$('.account-menu');if(menu&&!menu.contains(e.target))menu.open=false});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.account-menu')?.open){$('.account-menu').open=false;$('.profile-toggle').focus()}if(e.key==='Escape'&&tour)endTour();if(e.key==='Tab'&&tour){const buttons=$$('.tour-card button:not(:disabled)'),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
